#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum RunnerAerialFirstContact {
    AttackingReceiver,
    Attacking,
    Defending,
    Loose,
}

fn sample_aerial_first_contact(
    contest: RunnerFlightAerialContest,
    roll: f64,
) -> RunnerAerialFirstContact {
    let roll = roll.clamp(0.0, 1.0);
    let attacking_mass = contest.attacking_first_contact_probability.max(0.0);
    let receiver_mass = contest
        .receiver_first_contact_probability
        .clamp(0.0, attacking_mass);
    let defending_mass = contest.defending_first_contact_probability.max(0.0);
    let loose_mass = contest.loose_probability.max(0.0);
    let total = attacking_mass + defending_mass + loose_mass;
    if total <= 1e-12 {
        return RunnerAerialFirstContact::Loose;
    }
    let receiver = receiver_mass / total;
    let attacking = attacking_mass / total;
    let defending = (attacking_mass + defending_mass) / total;
    if roll < receiver {
        RunnerAerialFirstContact::AttackingReceiver
    } else if roll < attacking {
        RunnerAerialFirstContact::Attacking
    } else if roll < defending {
        RunnerAerialFirstContact::Defending
    } else {
        RunnerAerialFirstContact::Loose
    }
}

fn aerial_header_velocity(
    contact_pos: (f64, f64),
    target: (f64, f64),
    incoming_speed: f64,
) -> (f64, f64) {
    crate::physics::residual_ball_velocity(contact_pos, target, incoming_speed, 0.30)
}

fn corner_header_shot_release_probability(
    heading: f64,
    attacking_first_contact_probability: f64,
    contact_pos: (f64, f64),
    attacking_right: bool,
    config: &RunnerRuntimeConfig,
) -> f64 {
    let heading = (heading / 100.0).clamp(0.0, 1.0);
    let contest_control = attacking_first_contact_probability.clamp(0.0, 1.0);
    let goal = if attacking_right {
        (config.pitch_length, config.pitch_width * 0.5)
    } else {
        (0.0, config.pitch_width * 0.5)
    };
    let distance_factor = 1.0 - crate::physics::smoothstep(8.0, 22.0, distance(contact_pos, goal));
    let centrality = 1.0
        - ((contact_pos.1 - config.pitch_width * 0.5).abs() / (config.pitch_width * 0.5).max(1.0))
            .clamp(0.0, 1.0);
    ((0.18 + 0.42 * heading + 0.24 * contest_control)
        * (0.55 + 0.30 * distance_factor + 0.15 * centrality))
        .clamp(0.0, 0.88)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum RunnerRestartOrigin {
    GoalKick,
    Corner,
    FreeKick,
    Penalty,
}

impl RunnerRestartOrigin {
    fn event_tag(self) -> &'static str {
        match self {
            Self::GoalKick => "goal_kick_origin",
            Self::Corner => "corner_origin",
            Self::FreeKick => "free_kick_origin",
            Self::Penalty => "penalty_origin",
        }
    }

    fn requires_pass(self) -> bool {
        self == Self::GoalKick
    }

    fn restricts_first_action(self) -> bool {
        self != Self::Corner
    }
}

fn pending_restart_is_penalty(
    pending: Option<RunnerPendingRestartAction>,
    team_home: bool,
    player_idx: usize,
) -> bool {
    pending.is_some_and(|pending| {
        pending.origin == RunnerRestartOrigin::Penalty
            && pending.team_home == team_home
            && pending.player_idx == player_idx
    })
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct RunnerPendingRestartAction {
    origin: RunnerRestartOrigin,
    team_home: bool,
    player_idx: usize,
}

fn pending_restart_matches(
    pending: Option<RunnerPendingRestartAction>,
    team_home: bool,
    player_idx: usize,
) -> bool {
    pending.is_some_and(|pending| {
        pending.team_home == team_home
            && pending.player_idx == player_idx
            && pending.origin.restricts_first_action()
    })
}

fn pending_restart_requires_pass(
    pending: Option<RunnerPendingRestartAction>,
    team_home: bool,
    player_idx: usize,
) -> bool {
    pending.is_some_and(|pending| {
        pending.team_home == team_home
            && pending.player_idx == player_idx
            && pending.origin.requires_pass()
    })
}

fn pre_release_duel_allowed(
    pending: Option<RunnerPendingRestartAction>,
    team_home: bool,
    player_idx: usize,
) -> bool {
    !pending_restart_matches(pending, team_home, player_idx)
}

fn take_restart_origin_for_release(
    state: &mut RunnerMatchState,
    team_home: bool,
    player_idx: usize,
) -> Option<RunnerRestartOrigin> {
    state
        .pending_restart_action
        .filter(|pending| pending.team_home == team_home && pending.player_idx == player_idx)?;
    state
        .pending_restart_action
        .take()
        .map(|pending| pending.origin)
}

fn discard_unreleased_restart_at_period_end(state: &mut RunnerMatchState) {
    let pending = state.pending_restart_action.take();
    let dead_restart = state
        .dead_reason
        .as_deref()
        .zip(state.restart_team_home)
        .and_then(|(reason, team_home)| {
            let origin = match reason {
                "goal_kick" => RunnerRestartOrigin::GoalKick,
                "corner" => RunnerRestartOrigin::Corner,
                "offside" | "free_kick" => RunnerRestartOrigin::FreeKick,
                "penalty" => RunnerRestartOrigin::Penalty,
                _ => return None,
            };
            Some((origin, team_home))
        });
    let event_tail_restart = state.events.last().and_then(|event| {
        (event.get("event_type").and_then(serde_json::Value::as_str) == Some("restart"))
            .then(|| {
                let origin = match event.get("outcome").and_then(serde_json::Value::as_str) {
                    Some("goal_kick") => Some(RunnerRestartOrigin::GoalKick),
                    Some("corner") => Some(RunnerRestartOrigin::Corner),
                    Some("offside" | "free_kick") => Some(RunnerRestartOrigin::FreeKick),
                    Some("penalty") => Some(RunnerRestartOrigin::Penalty),
                    _ => None,
                }?;
                let team_home =
                    event.get("team_side").and_then(serde_json::Value::as_str) == Some("home");
                Some((origin, team_home))
            })
            .flatten()
    });
    let remove_recorded_restart = pending.is_some() || event_tail_restart.is_some();
    let Some((origin, team_home)) = pending
        .map(|pending| (pending.origin, pending.team_home))
        .or(dead_restart)
        .or(event_tail_restart)
    else {
        return;
    };
    let outcome = match origin {
        RunnerRestartOrigin::GoalKick => "goal_kick",
        RunnerRestartOrigin::Corner => "corner",
        RunnerRestartOrigin::FreeKick => {
            // Both ordinary free kicks and offside free kicks share this
            // release provenance. The most recent restart event identifies
            // which one was awarded.
            ""
        }
        RunnerRestartOrigin::Penalty => "penalty",
    };
    let recorded_restart_index = remove_recorded_restart
        .then(|| {
            state.events.iter().rposition(|event| {
                event.get("event_type").and_then(serde_json::Value::as_str) == Some("restart")
                    && event.get("team_side").and_then(serde_json::Value::as_str)
                        == Some(if team_home { "home" } else { "away" })
                    && (outcome.is_empty()
                        || event.get("outcome").and_then(serde_json::Value::as_str)
                            == Some(outcome))
            })
        })
        .flatten();
    if let Some(index) = recorded_restart_index {
        state.events.remove(index);
        for (event_index, event) in state.events.iter_mut().enumerate().skip(index) {
            if let Some(payload) = event.as_object_mut() {
                payload.insert("seq".to_string(), json!(event_index + 1));
            }
        }
        state.event_seq = state.events.len() as i32;
    }
    state.dead_reason = None;
    state.restart_team_home = None;
    state.restart_ticks_remaining = 0;
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum RunnerReplayFlightEnd {
    Blocked,
    Saved,
    Goal,
    Missed,
    Offside,
    Received,
    FirstTouchError,
    Intercepted,
    Loose,
    Cleared,
    OutOfPlay,
}

impl RunnerReplayFlightEnd {
    fn name(self) -> &'static str {
        match self {
            Self::Blocked => "blocked",
            Self::Saved => "saved",
            Self::Goal => "goal",
            Self::Missed => "missed",
            Self::Offside => "offside",
            Self::Received => "received",
            Self::FirstTouchError => "first_touch_error",
            Self::Intercepted => "intercepted",
            Self::Loose => "loose",
            Self::Cleared => "cleared",
            Self::OutOfPlay => "out_of_play",
        }
    }

    fn from_name(name: &str) -> Option<Self> {
        match name {
            "blocked" => Some(Self::Blocked),
            "saved" => Some(Self::Saved),
            "goal" => Some(Self::Goal),
            "missed" => Some(Self::Missed),
            "offside" => Some(Self::Offside),
            "received" => Some(Self::Received),
            "first_touch_error" => Some(Self::FirstTouchError),
            "intercepted" => Some(Self::Intercepted),
            "loose" => Some(Self::Loose),
            "cleared" => Some(Self::Cleared),
            "out_of_play" => Some(Self::OutOfPlay),
            _ => None,
        }
    }

    fn requires_replay_cut(self) -> bool {
        matches!(
            self,
            Self::Blocked
                | Self::Saved
                | Self::Goal
                | Self::Missed
                | Self::Offside
                | Self::OutOfPlay
        )
    }
}

