fn out_of_bounds_last_touch_team(
    pending_pass: Option<&RunnerPendingPass>,
    possession_team_home: Option<bool>,
) -> bool {
    pending_pass
        .map(|pending| pending.last_touch_team_home)
        .or(possession_team_home)
        .unwrap_or(true)
}

fn pass_control_is_direct_receipt(
    passer_team_home: bool,
    passer_idx: usize,
    intended_receiver_idx: Option<usize>,
    opponent_touch: bool,
    opponent_material_contact: bool,
    winner_home: bool,
    winner_idx: usize,
) -> bool {
    winner_home == passer_team_home
        && winner_idx != passer_idx
        && intended_receiver_idx == Some(winner_idx)
        && (!opponent_touch || !opponent_material_contact)
}

fn physical_last_touch_team(
    current_team_home: bool,
    strongest_contact: Option<crate::StableBallController>,
    physically_touched: bool,
) -> bool {
    strongest_contact
        .filter(|_| physically_touched)
        .map(|contact| contact.team_home)
        .unwrap_or(current_team_home)
}

