fn pass_terminal_speed_ratio_for(
    is_long: bool,
    target_is_space: bool,
    delivery_miss: bool,
) -> f64 {
    let controlled_delivery_ratio = match (is_long, target_is_space) {
        (false, false) => 0.24,
        (true, false) => 0.16,
        (false, true) => 0.30,
        (true, true) => 0.22,
    };
    if delivery_miss {
        (controlled_delivery_ratio + 0.10_f64).min(0.50)
    } else {
        controlled_delivery_ratio
    }
}

fn pass_terminal_speed_ratio(flight: &RunnerFlight) -> f64 {
    pass_terminal_speed_ratio_for(flight.is_long, flight.target_is_space, flight.delivery_miss)
}

#[derive(Clone, Copy, Debug)]
struct RunnerFlightInterval {
    start: crate::FlightCurveSample,
    end: crate::FlightCurveSample,
    elapsed_after: f64,
    consumed_fraction: f64,
    remaining_fraction: f64,
}

fn runner_flight_interval(
    flight: &RunnerFlight,
    elapsed_before: f64,
    available_fraction: f64,
) -> RunnerFlightInterval {
    let input = FlightTickInput {
        origin: flight.origin,
        target: flight.target,
        ticks_elapsed: 0,
        ticks_total: flight.ticks_total,
        speed: flight.speed,
        terminal_speed_ratio: if flight.kind == RunnerFlightKind::Pass {
            pass_terminal_speed_ratio(flight)
        } else {
            1.0
        },
    };
    let exact_ticks = distance(flight.origin, flight.target) / flight.speed.max(f64::EPSILON);
    let elapsed_before = elapsed_before.clamp(0.0, exact_ticks);
    let available_fraction = available_fraction.clamp(0.0, 1.0);
    let consumed_fraction = available_fraction.min((exact_ticks - elapsed_before).max(0.0));
    let elapsed_after = elapsed_before + consumed_fraction;
    RunnerFlightInterval {
        start: sample_ball_flight_curve(&input, elapsed_before),
        end: sample_ball_flight_curve(&input, elapsed_after),
        elapsed_after,
        consumed_fraction,
        remaining_fraction: available_fraction - consumed_fraction,
    }
}

fn pass_completion_replay_tick(
    flight: &RunnerFlight,
    interval: RunnerFlightInterval,
) -> f64 {
    flight.replay_start_tick + interval.elapsed_after
}

fn free_ball_control_replay_tick(replay_start_tick: f64, consumed_fraction: f64) -> f64 {
    replay_start_tick + consumed_fraction
}

fn runner_ground_interception_diagnostic(
    origin: (f64, f64),
    target: (f64, f64),
    speed: f64,
    terminal_speed_ratio: f64,
    defenders: &[RunnerPlayer],
    config: &RunnerRuntimeConfig,
) -> RunnerGroundInterceptionDiagnostic {
    let exact_ticks = distance(origin, target) / speed.max(f64::EPSILON);
    let curve = FlightTickInput {
        origin,
        target,
        ticks_elapsed: 0,
        ticks_total: exact_ticks.ceil().max(1.0) as i32,
        speed,
        terminal_speed_ratio,
    };
    let step_ticks = ball_contact_substep_ticks(config.tick_duration);
    let observation_ticks = step_ticks;
    let contact_radius = config.contest_radius.min(1.35);
    let mut diagnostic = RunnerGroundInterceptionDiagnostic {
        defender_idx: None,
        contact_pos: None,
        earliest_contact_ticks: None,
        minimum_separation_m: f64::INFINITY,
        minimum_separation_ticks: 0.0,
    };
    let mut elapsed = step_ticks;
    while elapsed <= exact_ticks + 1e-9 {
        let sample_ticks = elapsed.min(exact_ticks);
        let ball_pos = sample_ball_flight_curve(&curve, sample_ticks).position;
        for (defender_idx, defender) in defenders.iter().enumerate() {
            if defender.state == "stunned" {
                continue;
            }
            let observation = crate::physics::advance_player_motion_fraction(
                &crate::physics::PlayerMotionInput {
                    pos: defender.pos,
                    target: defender.target_pos,
                    velocity: defender.velocity,
                    speed_ability: defender.speed.round() as i32,
                    desired_speed: player_speed(
                        defender.speed.round() as i32,
                        config.player_max_speed,
                        config.player_min_speed,
                    ),
                    acceleration_scale: 1.0,
                    player_max_speed: config.player_max_speed,
                    player_min_speed: config.player_min_speed,
                    pitch_length: config.pitch_length,
                    pitch_width: config.pitch_width,
                },
                observation_ticks.min(sample_ticks),
            );
            let mut observed_defender = defender.clone();
            observed_defender.pos = observation.pos;
            observed_defender.velocity = observation.velocity;
            let projected = runner_aerial_player_input_at(
                defender_idx,
                &observed_defender,
                false,
                ball_pos,
                (sample_ticks - observation_ticks).max(0.0),
                config,
            );
            let separation = distance(projected.movement.projected_pos, ball_pos);
            if separation < diagnostic.minimum_separation_m {
                diagnostic.minimum_separation_m = separation;
                diagnostic.minimum_separation_ticks = sample_ticks;
            }
            let interior_contact = sample_ticks > observation_ticks + 1e-9
                && distance(origin, ball_pos) >= 2.0
                && distance(ball_pos, target) >= 2.0
                && sample_ticks + step_ticks <= exact_ticks + 1e-9;
            if interior_contact
                && separation <= contact_radius
                && diagnostic
                    .earliest_contact_ticks
                    .is_none_or(|earliest| sample_ticks < earliest)
            {
                diagnostic.defender_idx = Some(defender_idx);
                diagnostic.contact_pos = Some(ball_pos);
                diagnostic.earliest_contact_ticks = Some(sample_ticks);
            }
        }
        if sample_ticks >= exact_ticks - 1e-9 {
            break;
        }
        elapsed += step_ticks;
    }
    diagnostic
}

fn passer_release_contact_excluded(elapsed_ticks: f64, tick_duration: f64) -> bool {
    elapsed_ticks.max(0.0) * tick_duration.max(f64::EPSILON) < 1.0 - 1e-9
}

