struct MatchEventInput<'a> {
    tick: i32,
    half: i32,
    possession_id: i32,
    event_type: &'a str,
    team_home: bool,
    player: serde_json::Value,
    target_player: serde_json::Value,
    assist_player: serde_json::Value,
    outcome: &'a str,
    xg: f64,
    origin: Option<(f64, f64)>,
    target: Option<(f64, f64)>,
    tags: EventTags<'a>,
    score_before: Option<(i32, i32)>,
}

// A legal pass can carry release geometry, restart provenance, delivery
// quality, and a later passer-recovery/contact terminal in the same event.
// Keep enough inline capacity for that full accounting set.
const MAX_EVENT_TAGS: usize = 16;

struct EventTags<'a> {
    values: [&'a str; MAX_EVENT_TAGS],
    len: usize,
}

impl<'a> EventTags<'a> {
    fn empty() -> Self {
        Self {
            values: [""; MAX_EVENT_TAGS],
            len: 0,
        }
    }

    fn one(tag: &'a str) -> Self {
        let mut tags = Self::empty();
        tags.push(tag);
        tags
    }

    fn from_slice(values: &[&'a str]) -> Self {
        assert!(
            values.len() <= MAX_EVENT_TAGS,
            "event tags exceed fixed capacity"
        );
        let mut tags = Self::empty();
        tags.values[..values.len()].copy_from_slice(values);
        tags.len = values.len();
        tags
    }

    fn push(&mut self, tag: &'a str) {
        assert!(
            self.len < MAX_EVENT_TAGS,
            "event tags exceed fixed capacity"
        );
        self.values[self.len] = tag;
        self.len += 1;
    }

    fn as_slice(&self) -> &[&'a str] {
        &self.values[..self.len]
    }
}

fn event_player(player: Option<&RunnerPlayer>) -> serde_json::Value {
    player
        .map(|player| {
            json!({
                "player_id": player.player_id,
                "name": player.name,
                "color": player.color,
                "colored_name": player.colored_name,
                "position": player.position,
            })
        })
        .unwrap_or(serde_json::Value::Null)
}

fn event_position(position: Option<(f64, f64)>) -> serde_json::Value {
    position
        .map(|position| json!([round_one(position.0), round_one(position.1)]))
        .unwrap_or(serde_json::Value::Null)
}

fn record_match_event(
    state: &mut RunnerMatchState,
    config: &RunnerRuntimeConfig,
    input: MatchEventInput<'_>,
) {
    state.event_seq += 1;
    let match_second = (input.tick as f64 * config.tick_duration)
        .floor()
        .clamp(0.0, 90.0 * 60.0 - 1.0) as i32;
    let score_before = input
        .score_before
        .unwrap_or((state.home_score, state.away_score));
    state.events.push(json!({
        "seq": state.event_seq,
        "tick": input.tick,
        "match_second": match_second,
        "minute": match_second / 60,
        "second": match_second % 60,
        "half": input.half,
        "possession_id": input.possession_id,
        "event_type": input.event_type,
        "team_side": if input.team_home { "home" } else { "away" },
        "player": input.player,
        "target_player": input.target_player,
        "assist_player": input.assist_player,
        "outcome": input.outcome,
        "xg": round_two(input.xg),
        "xg_exact": input.xg,
        "score_before": [score_before.0, score_before.1],
        "score_after": [state.home_score, state.away_score],
        "origin": event_position(input.origin),
        "target": event_position(input.target),
        "tags": input.tags.as_slice(),
    }));
}

fn record_technical_control_error(
    state: &mut RunnerMatchState,
    config: &RunnerRuntimeConfig,
    tick: i32,
    half: i32,
    possession_id: i32,
    event_type: &'static str,
    team_home: bool,
    player: serde_json::Value,
    origin: (f64, f64),
    loose_pos: (f64, f64),
) {
    record_match_event(
        state,
        config,
        MatchEventInput {
            tick,
            half,
            possession_id,
            event_type,
            team_home,
            player,
            target_player: serde_json::Value::Null,
            assist_player: serde_json::Value::Null,
            outcome: "loose",
            xg: 0.0,
            origin: Some(origin),
            target: Some(loose_pos),
            tags: EventTags::from_slice(&["technical_error", "second_ball"]),
            score_before: None,
        },
    );
}

fn player_identity(players: &[RunnerPlayer], index: usize) -> serde_json::Value {
    event_player(players.get(index))
}

fn direct_shot_creator_idx(
    state: &RunnerMatchState,
    team_home: bool,
    shooter_idx: usize,
    players: &[RunnerPlayer],
) -> Option<usize> {
    let shooter_id = players.get(shooter_idx)?.player_id.to_string();
    for event in state.events.iter().rev() {
        if event.get("possession_id").and_then(|value| value.as_i64())
            != Some(state.possession_id as i64)
        {
            continue;
        }
        let event_type = event.get("event_type").and_then(|value| value.as_str());
        let is_second_ball = event
            .get("tags")
            .and_then(|value| value.as_array())
            .is_some_and(|tags| tags.iter().any(|tag| tag.as_str() == Some("second_ball")));
        if matches!(
            event_type,
            Some("recovery" | "interception" | "tackle" | "loose_ball")
        ) || is_second_ball
        {
            return None;
        }
        if event_type != Some("pass") {
            continue;
        }
        if event.get("team_side").and_then(|value| value.as_str())
            != Some(if team_home { "home" } else { "away" })
            || event.get("outcome").and_then(|value| value.as_str()) != Some("completed")
        {
            return None;
        }
        let target_id = event
            .get("target_player")
            .and_then(|value| value.get("player_id"))
            .map(serde_json::Value::to_string);
        if target_id.as_deref() != Some(shooter_id.as_str()) {
            return None;
        }
        let passer_id = event
            .get("player")
            .and_then(|value| value.get("player_id"))
            .map(serde_json::Value::to_string)?;
        return players
            .iter()
            .position(|player| player.player_id.to_string() == passer_id);
    }
    None
}

fn pass_event_tags(
    flight: &RunnerFlight,
    receive_pos: (f64, f64),
    config: &RunnerRuntimeConfig,
    home_attacking_right: bool,
) -> EventTags<'static> {
    let release_distance = distance(flight.origin, flight.target);
    let pass_stats = track_pass_stats(&PassStatInput {
        origin: flight.origin,
        target: receive_pos,
        attacking_right: attacking_right_for(flight.passer_team_home, home_attacking_right),
        pitch_length: config.pitch_length,
        pitch_width: config.pitch_width,
    });
    let release_pass_stats = track_pass_stats(&PassStatInput {
        origin: flight.origin,
        target: flight.target,
        attacking_right: attacking_right_for(flight.passer_team_home, home_attacking_right),
        pitch_length: config.pitch_length,
        pitch_width: config.pitch_width,
    });
    // Provider length classification belongs to the released geometry, not
    // the internal candidate family used to select speed and technique.
    let mut tags = EventTags::one(if crate::physics::is_long_pass_distance(release_distance) {
        "long"
    } else {
        "short"
    });
    tags.push(if flight.kind == RunnerFlightKind::AerialDelivery {
        "aerial"
    } else if flight.target_is_space {
        "space"
    } else {
        "feet"
    });
    tags.push(if release_distance < 10.0 {
        "distance_0_10"
    } else if release_distance < 20.0 {
        "distance_10_20"
    } else if release_distance < 30.0 {
        "distance_20_30"
    } else {
        "distance_30_plus"
    });
    if pass_stats.progressive_passes > 0 {
        tags.push("progressive");
    }
    if pass_stats.passes_into_final_third > 0 {
        tags.push("into_final_third");
    }
    if pass_stats.passes_into_box > 0 {
        tags.push("into_box");
    }
    // Cross/pass classification belongs to the released action. A delivery
    // error or contested touch may move the eventual control point into or
    // out of the box, but must not retrospectively change provider scope.
    if release_pass_stats.crosses_attempted > 0 {
        tags.push("cross");
    }
    if flight.kind == RunnerFlightKind::AerialDelivery
        && flight.restart_origin == Some(RunnerRestartOrigin::Corner)
    {
        tags.push("cross");
    }
    if flight.target_is_space && pass_stats.progressive_passes > 0 {
        tags.push("through_ball");
    }
    if let Some(origin) = flight.restart_origin {
        tags.push(origin.event_tag());
    }
    tags
}

fn pass_execution_tags(
    flight: &RunnerFlight,
    receive_pos: (f64, f64),
    config: &RunnerRuntimeConfig,
    home_attacking_right: bool,
) -> EventTags<'static> {
    let mut tags = pass_event_tags(flight, receive_pos, config, home_attacking_right);
    tags.push(if flight.delivery_miss {
        "delivery_error"
    } else {
        "delivery_clean"
    });
    tags
}

fn shot_event_tags(flight: &RunnerFlight, in_box: bool, outcome: &str) -> EventTags<'static> {
    let mut tags = shot_event_tags_for_xg(flight.xg, flight.on_target, in_box, outcome);
    if flight.aerial_contest.is_some() {
        tags.push("header");
    }
    if let Some(origin) = flight.restart_origin {
        tags.push(origin.event_tag());
    }
    if flight.aerial_contest.is_some() && flight.restart_origin == Some(RunnerRestartOrigin::Corner)
    {
        tags.push("corner_header");
    }
    tags
}

fn shot_event_tags_for_xg(
    xg: f64,
    on_target: bool,
    in_box: bool,
    outcome: &str,
) -> EventTags<'static> {
    let mut tags = EventTags::one(if in_box { "in_box" } else { "outside_box" });
    if on_target {
        tags.push("on_target");
    }
    if xg >= 0.3 {
        tags.push("big_chance");
    }
    if outcome == "goal" {
        tags.push("scored");
    }
    tags
}

fn out_of_play_restart_tag(reason: &str) -> &'static str {
    match reason {
        "goal_kick" => "goal_kick",
        "corner" => "corner",
        _ => "throw_in",
    }
}

