    #[test]
    fn aerial_receiver_does_not_redirect_toward_hidden_delivery_error() {
        let cards = (0..RUNNER_TEAM_SIZE)
            .map(|index| runner_test_card(format!("Player {index}").as_str(), 75.0, 75.0))
            .collect::<Vec<_>>();
        let mut home = build_players(&cards, formation_data("433"), true, 105.0, 68.0);
        let mut away = build_players(&cards, formation_data("433"), false, 105.0, 68.0);
        let config = runtime_config(&json!({}));
        let holder_idx = 5;
        let receiver_idx = 9;
        let origin = (20.0, 34.0);
        let intended_target = (52.0, 34.0);
        let miss_target = (52.0, 44.0);
        home[holder_idx].pos = origin;
        home[receiver_idx].pos = intended_target;
        home[receiver_idx].target_pos = intended_target;
        for (index, player) in home.iter_mut().enumerate() {
            if index != holder_idx && index != receiver_idx {
                player.pos = (20.0, 5.0 + index as f64 * 2.0);
                player.target_pos = player.pos;
            }
        }
        for (index, player) in away.iter_mut().enumerate() {
            player.pos = (85.0, 5.0 + index as f64 * 2.0);
            player.target_pos = player.pos;
        }

        let (_, _, hidden_error_receiver_contact) = runner_aerial_contest_snapshot(
            holder_idx,
            receiver_idx,
            origin,
            intended_target,
            miss_target,
            &home,
            &away,
            &config,
        );
        let (_, _, leaked_error_receiver_contact) = runner_aerial_contest_snapshot(
            holder_idx,
            receiver_idx,
            origin,
            miss_target,
            miss_target,
            &home,
            &away,
            &config,
        );

        assert!(
            leaked_error_receiver_contact > hidden_error_receiver_contact,
            "hidden={hidden_error_receiver_contact}, leaked={leaked_error_receiver_contact}"
        );
    }

