    #[test]
    fn completed_cross_uses_the_release_classification_not_the_control_point() {
        let (mut home, mut away, config, passer_idx, receiver_idx) = offside_snapshot_fixture(70.0);
        let origin = (80.0, 5.0);
        let released_target = (88.0, 10.0);
        let control_point = (95.0, 34.0);
        home[passer_idx].pos = origin;
        home[receiver_idx].pos = control_point;
        home[passer_idx].passes_attempted = 1;

        let mut state = runner_test_state();
        let flight = RunnerFlight {
            kind: RunnerFlightKind::Pass,
            replay_id: 1,
            replay_start_tick: 0.0,
            origin,
            target: released_target,
            ticks_elapsed: 1,
            ticks_total: 1,
            passer_idx,
            passer_team_home: true,
            intended_receiver_idx: Some(receiver_idx),
            offside_flags: [false; RUNNER_TEAM_SIZE],
            last_passer_team_home: Some(true),
            last_passer_idx: passer_idx as i32,
            on_target: false,
            speed: config.ball_pass_speed,
            xg: 0.0,
            gk_attributes: None,
            save_probability_override: None,
            is_long: false,
            target_is_space: true,
            retention_probability: 1.0,
            technical_probability: 1.0,
            technical_roll: 0.0,
            delivery_miss: false,
            arrival_snapshot: None,
            arrival_plan: None,
            clearance_transition: None,
            possession_id: state.possession_id,
            restart_origin: None,
            aerial_contest: None,
        };
        state.ball.pending_pass = Some(RunnerPendingPass {
            flight: flight.clone(),
            opponent_touch: false,
            opponent_material_contact: false,
            last_touch_team_home: true,
        });

        assert!(settle_pending_pass_control(
            &mut state,
            &config,
            12,
            1,
            receiver_idx,
            true,
            control_point,
            &mut home,
            &mut away,
            true,
        ));

        assert_eq!(home[passer_idx].passes_completed, 1);
        assert_eq!(home[passer_idx].crosses_attempted, 0);
        assert_eq!(home[passer_idx].crosses_completed, 0);
        assert_eq!(home[passer_idx].passes_into_box, 1);
        let completed_pass = state
            .events
            .iter()
            .find(|event| {
                event.get("event_type").and_then(serde_json::Value::as_str) == Some("pass")
                    && event.get("outcome").and_then(serde_json::Value::as_str) == Some("completed")
            })
            .expect("completed pass event");
        assert!(!completed_pass
            .get("tags")
            .and_then(serde_json::Value::as_array)
            .is_some_and(|tags| tags.iter().any(|tag| tag.as_str() == Some("cross"))));

        let completed_before_opponent_touch = home[passer_idx].passes_completed;
        state.events.clear();
        state.ball.pending_pass = Some(RunnerPendingPass {
            flight,
            opponent_touch: true,
            opponent_material_contact: false,
            last_touch_team_home: false,
        });
        assert!(settle_pending_pass_control(
            &mut state,
            &config,
            13,
            1,
            receiver_idx,
            true,
            control_point,
            &mut home,
            &mut away,
            true,
        ));
        assert_eq!(
            home[passer_idx].passes_completed,
            completed_before_opponent_touch + 1,
            "a non-material opponent touch must not erase the intended receiver's stable receipt"
        );
        assert!(state.events.iter().any(|event| {
            event.get("event_type").and_then(serde_json::Value::as_str) == Some("pass")
                && event.get("outcome").and_then(serde_json::Value::as_str)
                    == Some("completed")
                && event
                    .get("tags")
                    .and_then(serde_json::Value::as_array)
                    .is_some_and(|tags| {
                        tags.iter()
                            .any(|tag| tag.as_str() == Some("opponent_contact"))
                    })
        }));
    }

    #[test]
    fn direct_pass_receipt_requires_the_intended_receiver_and_no_material_opponent_contact() {
        assert!(pass_control_is_direct_receipt(
            true, 3, Some(6), false, false, true, 6,
        ));
        assert!(pass_control_is_direct_receipt(
            true, 3, Some(6), true, false, true, 6,
        ));
        assert!(!pass_control_is_direct_receipt(
            true, 3, Some(6), true, true, true, 6,
        ));
        assert!(!pass_control_is_direct_receipt(
            true, 3, Some(6), false, false, true, 7,
        ));
        assert!(!pass_control_is_direct_receipt(
            true, 3, Some(6), false, false, false, 6,
        ));
    }

