    #[test]
    fn zero_release_shot_is_replaced_by_a_reorientation_option() {
        let cards = (0..11)
            .map(|index| runner_test_card(format!("Home {index}").as_str(), 75.0, 75.0))
            .collect::<Vec<_>>();
        let opponents = (0..11)
            .map(|index| runner_test_card(format!("Away {index}").as_str(), 75.0, 75.0))
            .collect::<Vec<_>>();
        let teammates = build_players(&cards, formation_data("433"), true, 105.0, 68.0);
        let opponents = build_players(&opponents, formation_data("433"), false, 105.0, 68.0);
        let config = runtime_config(&json!({}));
        let cache = RefCell::new(HashMap::new());
        let holder_idx = 10;
        let current_value = 0.08;
        let control = PossessionControlState {
            facing_direction: 180.0,
            pressure_load: 1.0,
            containment_load: 1.0,
            forward_control: 0.0,
            turn_readiness: 0.0,
            release_window: 0.0,
            shape_readiness: 0.0,
            release_preparation: 0.0,
            stagnation_load: 0.0,
        };
        let shot = build_shot_candidate(
            holder_idx,
            &teammates[holder_idx],
            true,
            control,
            &teammates,
            &opponents,
            &[],
            current_value,
            true,
            1,
            &cache,
            &config,
        );
        let scratch = held_decision_scratch_with_full_observation(
            holder_idx, &teammates, &opponents, &config,
        );
        let hold = build_hold_candidate(
            holder_idx,
            &teammates[holder_idx],
            &scratch,
            current_value,
            0.0,
            shot.candidate_score,
            shot.xg,
            true,
            &config,
        )
        .expect("control option");
        let reorient =
            build_reorient_candidate(hold, &teammates[holder_idx], control, true, &config)
                .expect("misaligned control must have a reorientation option");
        let mut actions = vec![shot, reorient];

        retain_executable_held_actions(&mut actions, teammates[holder_idx].pos);

        assert!(
            actions
                .iter()
                .all(|action| !matches!(action.action, RunnerHeldAction::Shoot { .. })),
            "a shot that cannot release the ball must not remain a Bellman option"
        );
        assert!(matches!(
            actions.as_slice(),
            [RunnerEvaluatedAction {
                action: RunnerHeldAction::Reorient { .. },
                ..
            }]
        ));
        let reorient_value = actions[0].candidate_score;
        actions[0].set_test_outcome_value(reorient_value);
        assert_eq!(runner_bellman_best_action_index(&actions), Some(0));
    }

    #[test]
    fn reorientation_duration_matches_the_single_preparation_tick() {
        let cards = (0..11)
            .map(|index| runner_test_card(format!("Home {index}").as_str(), 75.0, 75.0))
            .collect::<Vec<_>>();
        let opponent_cards = (0..11)
            .map(|index| runner_test_card(format!("Away {index}").as_str(), 75.0, 75.0))
            .collect::<Vec<_>>();
        let mut teammates = build_players(&cards, formation_data("433"), true, 105.0, 68.0);
        let opponents = build_players(&opponent_cards, formation_data("433"), false, 105.0, 68.0);
        let holder_idx = 9;
        let origin = (58.0, 18.0);
        teammates[holder_idx].pos = origin;
        teammates[holder_idx].target_pos = origin;
        teammates[holder_idx].facing_direction = 180.0;
        let config = runtime_config(&json!({}));
        let signals = crate::team_plan_signals(crate::TeamPlanKind::Advance);
        let scratch = held_decision_scratch_with_full_observation(
            holder_idx, &teammates, &opponents, &config,
        );
        let hold = build_hold_candidate(
            holder_idx,
            &teammates[holder_idx],
            &scratch,
            0.02,
            1.0,
            0.0,
            0.0,
            true,
            &config,
        )
        .expect("control option");
        let mut reorient = build_reorient_candidate(
            hold,
            &teammates[holder_idx],
            PossessionControlState {
                facing_direction: 180.0,
                ..PossessionControlState::default()
            },
            true,
            &config,
        )
        .expect("misaligned control must have a reorientation option");
        let RunnerHeldAction::Reorient { target } = reorient.action else {
            panic!("expected reorientation action");
        };

        assert_eq!(
            reorient.candidate_score, 0.0,
            "reorientation must not expose the inherited hold heuristic as its candidate score"
        );
        assert_eq!(
            runner_option_duration_ticks(&reorient, origin, signals, &config),
            1,
            "explicit reorientation and an unreleased shot both execute one preparation contact"
        );
        assert_eq!(
            runner_option_duration_seconds(
                &reorient,
                origin,
                signals,
                PossessionControlState {
                    facing_direction: 180.0,
                    ..PossessionControlState::default()
                },
                &config,
            ),
            crate::possession_control::reorient_control_duration_seconds(
                PossessionControlState {
                    facing_direction: 180.0,
                    ..PossessionControlState::default()
                },
                angle_between_points(origin, target),
            )
            .min(config.tick_duration),
            "temporal discount must use the same physical reorientation window"
        );

        let mut state = runner_test_state();
        reorient.set_test_outcome_value(0.02);
        start_action_commitment(
            &mut state,
            reorient.action,
            Some(reorient),
            origin,
            signals,
            0.0,
            0.0,
            &config,
        );
        let commitment = state
            .action_commitment
            .expect("reorientation must create an execution commitment");
        assert_eq!(
            commitment.initial_ticks, 1,
            "execution commitment must not repeat a one-tick turn"
        );
    }

    #[test]
    fn reorientation_budget_matches_the_heading_from_its_moving_endpoint() {
        let cards = (0..11)
            .map(|index| runner_test_card(format!("Player {index}").as_str(), 80.0, 80.0))
            .collect::<Vec<_>>();
        let mut teammates = build_players(&cards, formation_data("442"), true, 105.0, 68.0);
        let mut opponents = build_players(&cards, formation_data("442"), false, 105.0, 68.0);
        let config = runtime_config(&json!({}));
        let holder_idx = 6;
        let target = (105.0, 34.0);
        teammates[holder_idx].pos = (50.0, 20.0);
        teammates[holder_idx].velocity = (0.0, 2.0);
        teammates[holder_idx].facing_direction = 40.0;
        for opponent in &mut opponents {
            opponent.pos = (100.0, 60.0);
        }
        let control = PossessionControlState {
            facing_direction: 40.0,
            pressure_load: 0.0,
            containment_load: 0.0,
            forward_control: 0.8,
            turn_readiness: 1.0,
            release_window: 0.9,
            shape_readiness: 0.9,
            release_preparation: 0.8,
            stagnation_load: 0.0,
        };
        let fraction = runner_reorient_elapsed_fraction(
            RunnerHeldAction::Reorient { target },
            &teammates[holder_idx],
            &opponents,
            control,
            true,
            &config,
        );
        let execution_opponents = opponents
            .iter()
            .map(|player| ExecutionOpponent {
                pos: player.pos,
                is_goalkeeper: player.position == "GK",
            })
            .collect::<Vec<_>>();
        let hold = hold_phase_plan(&HoldPhasePlanInput {
            transition: None,
            holder_pos: teammates[holder_idx].pos,
            velocity: teammates[holder_idx].velocity,
            speed_ability: teammates[holder_idx].speed.round() as i32,
            dribbling: teammates[holder_idx].dribbling,
            attacking_right: true,
            pitch_length: config.pitch_length,
            pitch_width: config.pitch_width,
            player_max_speed: config.player_max_speed,
            player_min_speed: config.player_min_speed,
            carry_error_divisor: config.carry_error_divisor,
            opponents: &execution_opponents,
            opportunity_target: None,
            error_roll: 1.0,
            loose_x_roll: 0.5,
            loose_y_roll: 0.5,
            elapsed_fraction: fraction,
        });
        let endpoint_fraction = crate::possession_control::reorient_control_duration_seconds(
            control,
            angle_between_points(hold.new_pos, target),
        ) / config.tick_duration;

        assert!(fraction > 0.0 && fraction < 1.0);
        assert!(distance(hold.new_pos, teammates[holder_idx].pos) > 1e-9);
        assert!((fraction - endpoint_fraction).abs() < 1e-12);
    }

    #[test]
    fn reorientation_releases_one_follow_up_pass_within_the_same_tick_budget() {
        let cards = (0..11)
            .map(|index| runner_test_card(format!("Player {index}").as_str(), 80.0, 80.0))
            .collect::<Vec<_>>();
        let mut home = build_players(&cards, formation_data("442"), true, 105.0, 68.0);
        let mut away = build_players(&cards, formation_data("442"), false, 105.0, 68.0);
        let config = runtime_config(&json!({
            "iq_noise_scale": 0.0,
            "goal_noise_scale": 0.0,
            "carry_error_divisor": 1_000_000_000.0,
            "runner_forced_actions": ["pass"],
            "runner_forced_pass_target": [80.0, 34.0],
        }));
        let holder_idx = 6;
        let receiver_idx = 8;
        let origin = (50.0, 34.0);
        home[holder_idx].pos = origin;
        home[holder_idx].target_pos = origin;
        home[holder_idx].facing_direction = 20.0;
        home[receiver_idx].pos = (80.0, 34.0);
        home[receiver_idx].target_pos = home[receiver_idx].pos;
        for (index, defender) in away.iter_mut().enumerate() {
            defender.pos = (95.0, 8.0 + index as f64 * 5.0);
            defender.target_pos = defender.pos;
            defender.last_def_action = "hold_position".to_string();
        }
        let mut state = runner_test_state();
        state.trace_enabled = true;
        give_ball_to_player(
            &mut state,
            &mut home,
            &mut away,
            holder_idx,
            true,
            origin,
            None,
            true,
            &config,
        );
        state.ball.control = PossessionControlState {
            facing_direction: 20.0,
            pressure_load: 0.0,
            containment_load: 0.0,
            forward_control: 0.90,
            turn_readiness: 1.0,
            release_window: 0.95,
            shape_readiness: 0.90,
            release_preparation: 0.95,
            stagnation_load: 0.0,
        };
        let scratch =
            held_decision_scratch_with_full_observation(holder_idx, &home, &away, &config);
        let hold = build_hold_candidate(
            holder_idx,
            &home[holder_idx],
            &scratch,
            0.02,
            1.0,
            0.0,
            0.0,
            true,
            &config,
        )
        .expect("control option");
        let mut reorient = build_reorient_candidate(
            hold,
            &home[holder_idx],
            state.ball.control,
            true,
            &config,
        )
        .expect("misaligned control must have a reorientation option");
        reorient.set_test_outcome_value(0.02);
        let elapsed_fraction = runner_control_action_elapsed_fraction(
            reorient.action,
            origin,
            state.ball.control,
            &config,
        );
        assert!(elapsed_fraction > 0.0 && elapsed_fraction < 0.5);
        start_action_commitment(
            &mut state,
            reorient.action,
            Some(reorient),
            origin,
            crate::team_plan_signals(crate::TeamPlanKind::Advance),
            0.0,
            0.0,
            &config,
        );
        let mut rng = RunnerRng::new(20260806);
        let mut held_tick_arena = RunnerHeldTickArena::new();

        tick_match(
            &mut state,
            1,
            1,
            &mut home,
            &mut away,
            &config,
            true,
            &mut held_tick_arena,
            &mut rng,
        );

        let reorient_index = state
            .trace_entries
            .iter()
            .position(|entry| {
                entry.get("action").and_then(serde_json::Value::as_str) == Some("reorient")
                    && entry.get("tick").and_then(serde_json::Value::as_i64) == Some(1)
            })
            .expect("the committed reorientation must execute");
        let follow_up_index = state
            .trace_entries
            .iter()
            .position(|entry| {
                entry.get("event").and_then(serde_json::Value::as_str)
                    == Some("receipt_fast_pass")
            })
            .expect("the remaining reorientation budget must release a pass");
        let pass_entries = state
            .trace_entries
            .iter()
            .enumerate()
            .filter(|(_, entry)| {
                entry.get("action").and_then(serde_json::Value::as_str) == Some("pass")
                    && entry.get("tick").and_then(serde_json::Value::as_i64) == Some(1)
            })
            .collect::<Vec<_>>();
        assert!(reorient_index < follow_up_index);
        assert_eq!(pass_entries.len(), 1, "one tick permits only one follow-up action");
        assert!(follow_up_index < pass_entries[0].0);
        assert_eq!(home[holder_idx].passes_attempted, 1);
        assert_eq!(state.held_action_cursor, 1);
        assert!(state.ball.state != RunnerBallState::Held);
        let recorded_fraction = state.trace_entries[reorient_index]
            .get("elapsed_fraction")
            .and_then(serde_json::Value::as_f64)
            .expect("reorientation trace must expose its physical budget");
        assert!((recorded_fraction - elapsed_fraction).abs() < 1e-12);
    }

