    #[test]
    fn failed_pass_four_point_quadrature_exposes_spatial_integration_bias() {
        let cards = (0..11)
            .map(|index| runner_test_card(format!("Home {index}").as_str(), 75.0, 75.0))
            .collect::<Vec<_>>();
        let opponent_cards = (0..11)
            .map(|index| runner_test_card(format!("Away {index}").as_str(), 75.0, 75.0))
            .collect::<Vec<_>>();
        let mut teammates = build_players(&cards, formation_data("433"), true, 105.0, 68.0);
        let mut opponents =
            build_players(&opponent_cards, formation_data("433"), false, 105.0, 68.0);
        let holder_idx = 6;
        let receiver_idx = 8;
        let origin = (44.0, 34.0);
        let target = (64.0, 38.0);
        teammates[holder_idx].pos = origin;
        teammates[holder_idx].target_pos = origin;
        teammates[holder_idx].short_passing = 74.0;
        teammates[receiver_idx].pos = (62.0, 37.0);
        teammates[receiver_idx].target_pos = target;
        teammates[7].pos = (59.0, 44.0);
        teammates[7].target_pos = teammates[7].pos;
        for opponent in &mut opponents {
            opponent.pos = (82.0, opponent.pos.1);
            opponent.target_pos = opponent.pos;
        }
        opponents[4].pos = (67.0, 35.0);
        opponents[4].target_pos = opponents[4].pos;
        let config = runtime_config(&json!({}));
        let decision_scratch = held_decision_scratch_with_full_observation(
            holder_idx, &teammates, &opponents, &config,
        );
        let hold = build_hold_candidate(
            holder_idx,
            &teammates[holder_idx],
            &decision_scratch,
            0.0,
            0.0,
            0.0,
            0.0,
            true,
            &config,
        )
        .expect("control candidate");
        let action = RunnerEvaluatedAction {
            action: RunnerHeldAction::Pass {
                receiver_idx,
                target,
                is_long: false,
                lofted: false,
                lane_risk: 0.08,
                retention_probability: 0.72,
                technical_probability: 0.72,
            },
            success_prob: 0.72,
            ..hold
        };
        let signals = crate::team_plan_signals(crate::TeamPlanKind::Recycle);
        let defending_signals = crate::team_plan_signals(crate::TeamPlanKind::DefendBlock);
        let integrate = |action: &RunnerEvaluatedAction,
                         integration_target: (f64, f64),
                         angle_steps,
                         radius_steps| {
            let mut projection_scratch = RunnerProjectedTeamProjectionScratch::new();
            let mut second_ball_inputs = RunnerSecondBallInputs::empty();
            second_ball_inputs.prepare_projected_players(&teammates, &opponents, &config);
            runner_transition_model::projected_failed_pass_grid_probabilities(
                action,
                holder_idx,
                origin,
                integration_target,
                &teammates,
                &opponents,
                true,
                "attacking",
                "defending",
                signals,
                defending_signals,
                angle_steps,
                radius_steps,
                &config,
                &mut projection_scratch,
                &mut second_ball_inputs,
            )
        };
        let four_point = integrate(&action, target, 4, 1);
        let four_by_two = integrate(&action, target, 4, 2);
        let eight_by_one = integrate(&action, target, 8, 1);
        let eight_by_four = integrate(&action, target, 8, 4);
        let dense = integrate(&action, target, 16, 8);

        assert!((four_point.0 + four_point.1 + four_point.2 - 1.0).abs() < 1e-9);
        assert!((dense.0 + dense.1 + dense.2 - 1.0).abs() < 1e-9);
        assert!(
            (four_point.0 - dense.0).abs() > 0.07,
            "the current midpoint-only radius quadrature must expose the measured retained-control bias: four={four_point:?}, dense={dense:?}"
        );
        let distribution_error = |sample: (f64, f64, f64, f64)| {
            (sample.0 - dense.0).abs()
                + (sample.1 - dense.1).abs()
                + (sample.2 - dense.2).abs()
                + (sample.3 - dense.3).abs()
        };
        assert!(
            distribution_error(eight_by_four) < distribution_error(four_point),
            "a dense angle-radius grid must reduce total probability-distribution bias: bounded={eight_by_four:?}, dense={dense:?}, old_four={four_point:?}"
        );
        assert!(
            distribution_error(eight_by_one) < distribution_error(four_point),
            "eight angular points at one representative radius must improve the production quadrature: eight={eight_by_one:?}, dense={dense:?}, old_four={four_point:?}"
        );
        assert!(
            distribution_error(four_by_two) < distribution_error(four_point),
            "two equal-area radial strata must improve the production quadrature: layered={four_by_two:?}, dense={dense:?}, old_four={four_point:?}"
        );
        let boundary_target = (64.0, 1.8);
        let mut boundary_action = action.clone();
        if let RunnerHeldAction::Pass { target, .. } = &mut boundary_action.action {
            *target = boundary_target;
        }
        let boundary_four = integrate(&boundary_action, boundary_target, 4, 1);
        let boundary_bounded = integrate(&boundary_action, boundary_target, 8, 4);
        let boundary_dense = integrate(&boundary_action, boundary_target, 16, 8);
        eprintln!(
            "failed-pass quadrature boundary: four={boundary_four:?}, bounded={boundary_bounded:?}, dense={boundary_dense:?}"
        );
        assert!(boundary_dense.3 > 0.0);
    }

