    #[test]
    fn live_ground_lateral_pass_continues_from_a_glancing_defensive_contact() {
        let cards = (0..11)
            .map(|index| runner_test_card(format!("Player {index}").as_str(), 75.0, 75.0))
            .collect::<Vec<_>>();
        let mut home = build_players(&cards, formation_data("442"), true, 105.0, 68.0);
        let mut away = build_players(&cards, formation_data("442"), false, 105.0, 68.0);
        let config = runtime_config(&json!({
            "player_max_speed": 8.0,
            "player_min_speed": 2.5,
            "first_touch_error_divisor": 1_000_000_000.0,
            "iq_noise_scale": 0.0,
            "goal_noise_scale": 0.0,
        }));
        let passer_idx = 0;
        let receiver_idx = 1;
        let interceptor_idx = 7;
        let origin = (52.0, 6.0);
        let target = (52.0, 56.0);
        for player in &mut home {
            player.pos = (5.0, 5.0);
            player.target_pos = player.pos;
        }
        for player in &mut away {
            player.pos = (100.0, 5.0);
            player.target_pos = player.pos;
        }
        home[passer_idx].pos = origin;
        home[passer_idx].target_pos = origin;
        home[receiver_idx].pos = target;
        home[receiver_idx].target_pos = target;
        away[interceptor_idx].pos = (52.0, 30.0);
        away[interceptor_idx].target_pos = away[interceptor_idx].pos;

        let arrival_snapshot =
            runner_pass_arrival_snapshot(passer_idx, Some(receiver_idx), target, &home, &away);
        let arrival = runner_pass_arrival_plan_from_snapshot(
            arrival_snapshot,
            target,
            origin,
            config.ball_pass_speed,
            4.0,
            &config,
        );
        let mut state = runner_test_state();
        state.trace_enabled = true;
        state.ball.state = RunnerBallState::InFlight;
        state.ball.position = origin;
        state.ball.flight = Some(RunnerFlight {
            kind: RunnerFlightKind::Pass,
            replay_id: 1,
            replay_start_tick: 0.0,
            origin,
            target,
            ticks_elapsed: 0,
            ticks_total: 4,
            passer_idx,
            passer_team_home: true,
            intended_receiver_idx: Some(receiver_idx),
            offside_flags: [false; RUNNER_TEAM_SIZE],
            last_passer_team_home: None,
            last_passer_idx: -1,
            on_target: false,
            speed: config.ball_pass_speed,
            xg: 0.0,
            gk_attributes: None,
            save_probability_override: None,
            is_long: false,
            target_is_space: false,
            retention_probability: 1.0,
            technical_probability: 1.0,
            technical_roll: 0.0,
            delivery_miss: false,
            arrival_snapshot: Some(arrival_snapshot),
            arrival_plan: Some(arrival),
            clearance_transition: None,
            possession_id: state.possession_id,
            restart_origin: None,
            aerial_contest: None,
        });
        let mut rng = RunnerRng::new(20260714);
        let mut held_tick_arena = RunnerHeldTickArena::new();
        let mut pass_control_states = Vec::new();

        let mut contact_tick = None;
        for tick in 1..=4 {
            tick_match(
                &mut state,
                tick,
                1,
                &mut home,
                &mut away,
                &config,
                true,
                &mut held_tick_arena,
                &mut rng,
            );
            pass_control_states.push((
                tick,
                state.ball.state,
                state.ball.pending_pass.is_some(),
                state.ball.control_claims,
            ));
            if state.ball.state != RunnerBallState::InFlight {
                contact_tick = Some(tick);
                break;
            }
        }
        let contact_tick = contact_tick.expect("the live defender must contact the pass");
        assert!(state.ball.flight.is_none());
        assert!(
            distance(state.ball.position, target) > config.contest_radius,
            "the ball must not continue through the interceptor to the original target"
        );
        assert!(
            state.ball.position.1 > away[interceptor_idx].pos.1 + 0.1,
            "a glancing touch must switch to free motion for the rest of the tick, not freeze at contact: ball={:?}, interceptor={:?}",
            state.ball.position,
            away[interceptor_idx].pos
        );
        if state.ball.state == RunnerBallState::FreeBall {
            assert_eq!(state.ball.holder_team_home, None);
            assert_eq!(state.ball.holder_idx, None);
            assert_eq!(
                state.ball.control_claims.away.player_index,
                Some(interceptor_idx)
            );
            assert!(state.ball.control_claims.away.confidence > 0.0);
            let release_speed =
                config.ball_pass_speed * (2.0 - pass_terminal_speed_ratio_for(true, false, false));
            assert!(
                (state.ball.loose_velocity.0 * state.ball.loose_velocity.0
                    + state.ball.loose_velocity.1 * state.ball.loose_velocity.1)
                    .sqrt()
                    < release_speed,
                "the physical contact must keep the ball below its release-speed envelope"
            );
            assert_eq!(away[interceptor_idx].interceptions, 0);
            assert!(state.ball.pending_pass.is_some());
            for tick in (contact_tick + 1)..=(contact_tick + 12) {
                tick_match(
                    &mut state,
                    tick,
                    1,
                    &mut home,
                    &mut away,
                    &config,
                    true,
                    &mut held_tick_arena,
                    &mut rng,
                );
                pass_control_states.push((
                    tick,
                    state.ball.state,
                    state.ball.pending_pass.is_some(),
                    state.ball.control_claims,
                ));
                if state.ball.state == RunnerBallState::Held {
                    break;
                }
            }
        }
        assert_eq!(state.ball.state, RunnerBallState::Held);
        let controller_home = state
            .ball
            .holder_team_home
            .expect("continuous contact must eventually establish control");
        let controller_idx = state
            .ball
            .holder_idx
            .expect("continuous contact must identify the controller");
        assert!(state.ball.pending_pass.is_none());
        if controller_home {
            assert_eq!(home[passer_idx].passes_completed, 0);
            assert_eq!(away[interceptor_idx].interceptions, 0);
            assert!(state.trace_entries.iter().any(|entry| {
                entry.get("event").and_then(serde_json::Value::as_str) == Some("pass_loose")
                    && entry
                        .get("opponent_material_contact")
                        .and_then(serde_json::Value::as_bool)
                        == Some(true)
            }));
        } else {
            let controlled_interception = state.trace_entries.iter().any(|entry| {
                entry.get("event").and_then(serde_json::Value::as_str) == Some("interception")
                    && entry
                        .get("control_model")
                        .and_then(serde_json::Value::as_str)
                        == Some("continuous_contact")
            });
            let deflected_out_of_play = state.trace_entries.iter().any(|entry| {
                entry.get("event").and_then(serde_json::Value::as_str) == Some("out_of_bounds")
                    && entry.get("source").and_then(serde_json::Value::as_str)
                        == Some("continuous_ball")
            });
            assert_eq!(
                away[controller_idx].interceptions,
                i32::from(controlled_interception)
            );
            assert!(
                controlled_interception || deflected_out_of_play,
                "the deflected pass must resolve through later physical control or leave play"
            );
        }
    }

    #[test]
    fn goalkeeper_stably_controls_a_slow_close_back_pass_in_the_penalty_area() {
        let cards = (0..RUNNER_TEAM_SIZE)
            .map(|index| runner_test_card(format!("Player {index}").as_str(), 80.0, 80.0))
            .collect::<Vec<_>>();
        let mut home = build_players(&cards, formation_data("442"), true, 105.0, 68.0);
        let mut away = build_players(&cards, formation_data("442"), false, 105.0, 68.0);
        let config = runtime_config(&json!({}));
        let goalkeeper_idx = home
            .iter()
            .position(|player| player.position == "GK")
            .expect("the formation must contain a goalkeeper");
        let passer_idx = 5;
        let origin = (8.0, 34.0);
        let target = (4.0, 34.0);
        for player in &mut home {
            player.pos = (40.0, 5.0);
            player.target_pos = player.pos;
        }
        for player in &mut away {
            player.pos = (90.0, 63.0);
            player.target_pos = player.pos;
        }
        home[passer_idx].pos = origin;
        home[passer_idx].target_pos = origin;
        home[goalkeeper_idx].pos = target;
        home[goalkeeper_idx].target_pos = target;
        home[goalkeeper_idx].facing_direction = 180.0;
        let home_start_positions = std::array::from_fn(|index| home[index].pos);
        let away_start_positions = std::array::from_fn(|index| away[index].pos);
        let flight = RunnerFlight {
            kind: RunnerFlightKind::Pass,
            replay_id: 1,
            replay_start_tick: 0.0,
            origin,
            target,
            ticks_elapsed: 1,
            ticks_total: 1,
            passer_idx,
            passer_team_home: true,
            intended_receiver_idx: Some(goalkeeper_idx),
            offside_flags: [false; RUNNER_TEAM_SIZE],
            last_passer_team_home: None,
            last_passer_idx: -1,
            on_target: false,
            speed: 4.0,
            xg: 0.0,
            gk_attributes: None,
            save_probability_override: None,
            is_long: false,
            target_is_space: false,
            retention_probability: 1.0,
            technical_probability: 1.0,
            technical_roll: 0.0,
            delivery_miss: false,
            arrival_snapshot: None,
            arrival_plan: None,
            clearance_transition: None,
            possession_id: 1,
            restart_origin: None,
            aerial_contest: None,
        };
        let mut state = runner_test_state();
        state.ball.state = RunnerBallState::InFlight;
        state.ball.position = origin;

        let contact_outcome = resolve_pass_flight_contacts(
            &mut state,
            &flight,
            0,
            origin,
            target,
            (-0.96, 0.0),
            &home,
            &away,
            &home_start_positions,
            &away_start_positions,
            true,
            &config,
            0.0,
            1.0,
        );

        assert!(contact_outcome.ended_flight);
        assert_eq!(
            contact_outcome
                .stable_controller
                .map(|controller| (controller.team_home, controller.player_index)),
            Some((true, goalkeeper_idx))
        );
        assert_eq!(
            state
                .ball
                .pending_pass
                .as_ref()
                .map(|pending| pending.last_touch_team_home),
            Some(true)
        );
    }

    fn untouched_pass_keeps_its_incoming_velocity_at_the_planned_target() {
        let cards = (0..RUNNER_TEAM_SIZE)
            .map(|index| runner_test_card(format!("Player {index}").as_str(), 75.0, 75.0))
            .collect::<Vec<_>>();
        let mut home = build_players(&cards, formation_data("442"), true, 105.0, 68.0);
        let mut away = build_players(&cards, formation_data("442"), false, 105.0, 68.0);
        for player in &mut home {
            player.pos = (5.0, 5.0);
            player.target_pos = player.pos;
        }
        for player in &mut away {
            player.pos = (100.0, 63.0);
            player.target_pos = player.pos;
        }
        let config = runtime_config(&json!({}));
        let origin = (50.0, 20.0);
        let target = (50.0, 32.0);
        let previous_ball_pos = (50.0, 26.0);
        let flight = RunnerFlight {
            kind: RunnerFlightKind::Pass,
            replay_id: 1,
            replay_start_tick: 0.0,
            origin,
            target,
            ticks_elapsed: 2,
            ticks_total: 2,
            passer_idx: 0,
            passer_team_home: true,
            intended_receiver_idx: Some(1),
            offside_flags: [false; RUNNER_TEAM_SIZE],
            last_passer_team_home: None,
            last_passer_idx: -1,
            on_target: true,
            speed: 6.0,
            xg: 0.0,
            gk_attributes: None,
            save_probability_override: None,
            is_long: false,
            target_is_space: false,
            retention_probability: 1.0,
            technical_probability: 1.0,
            technical_roll: 0.0,
            delivery_miss: false,
            arrival_snapshot: None,
            arrival_plan: None,
            clearance_transition: None,
            possession_id: 1,
            restart_origin: None,
            aerial_contest: None,
        };
        assert!((pass_terminal_speed_ratio(&flight) - 0.24).abs() <= 1e-9);
        let mut space_delivery = flight.clone();
        space_delivery.is_long = true;
        space_delivery.target_is_space = true;
        assert!((pass_terminal_speed_ratio(&space_delivery) - 0.22).abs() <= 1e-9);
        space_delivery.delivery_miss = true;
        assert!((pass_terminal_speed_ratio(&space_delivery) - 0.32).abs() <= 1e-9);
        let mut state = runner_test_state();
        state.ball.state = RunnerBallState::InFlight;
        state.ball.position = previous_ball_pos;
        let home_start_positions = std::array::from_fn(|index| home[index].pos);
        let away_start_positions = std::array::from_fn(|index| away[index].pos);

        let contact_outcome = resolve_pass_flight_contacts(
            &mut state,
            &flight,
            0,
            previous_ball_pos,
            target,
            (0.0, 6.0),
            &home,
            &away,
            &home_start_positions,
            &away_start_positions,
            true,
            &config,
            0.0,
            1.0,
        );

        assert!(contact_outcome.ended_flight);
        assert!(contact_outcome.stable_controller.is_none());
        assert_eq!(state.ball.state, RunnerBallState::FreeBall);
        assert!(state.ball.loose_velocity.0.abs() <= 1e-9);
        assert!((state.ball.loose_velocity.1 - 6.0).abs() <= 1e-9);
    }

    #[test]
    fn teammate_in_the_corridor_preserves_the_pass_target_and_receiver_run() {
        let cards = (0..11)
            .map(|index| runner_test_card(format!("Player {index}").as_str(), 75.0, 75.0))
            .collect::<Vec<_>>();
        let mut home = build_players(&cards, formation_data("442"), true, 105.0, 68.0);
        let mut away = build_players(&cards, formation_data("442"), false, 105.0, 68.0);
        let config = runtime_config(&json!({
            "player_max_speed": 8.0,
            "player_min_speed": 2.5,
            "first_touch_error_divisor": 1_000_000_000.0,
            "iq_noise_scale": 0.0,
            "goal_noise_scale": 0.0,
        }));
        let passer_idx = 0;
        let receiver_idx = 1;
        let supporting_idx = 2;
        let origin = (52.0, 6.0);
        let target = (52.0, 62.0);
        for player in &mut home {
            player.pos = (5.0, 5.0);
            player.target_pos = player.pos;
        }
        for player in &mut away {
            player.pos = (100.0, 5.0);
            player.target_pos = player.pos;
        }
        home[passer_idx].pos = origin;
        home[passer_idx].target_pos = origin;
        home[receiver_idx].pos = (52.0, 54.0);
        home[receiver_idx].target_pos = home[receiver_idx].pos;
        home[supporting_idx].pos = (52.0, 34.0);
        home[supporting_idx].target_pos = home[supporting_idx].pos;

        let arrival_snapshot =
            runner_pass_arrival_snapshot(passer_idx, Some(receiver_idx), target, &home, &away);
        let arrival = runner_pass_arrival_plan_from_snapshot(
            arrival_snapshot,
            target,
            origin,
            config.ball_pass_speed,
            4.0,
            &config,
        );
        assert_eq!(arrival.outcome_code, 0);
        assert_eq!(arrival.contact_pos, target);
        assert_eq!(arrival.contact_tick, 4);

        let mut state = runner_test_state();
        state.ball.state = RunnerBallState::InFlight;
        state.ball.position = origin;
        let flight = RunnerFlight {
            kind: RunnerFlightKind::Pass,
            replay_id: 1,
            replay_start_tick: 0.0,
            origin,
            target,
            ticks_elapsed: 0,
            ticks_total: 4,
            passer_idx,
            passer_team_home: true,
            intended_receiver_idx: Some(receiver_idx),
            offside_flags: [false; RUNNER_TEAM_SIZE],
            last_passer_team_home: None,
            last_passer_idx: -1,
            on_target: false,
            speed: config.ball_pass_speed,
            xg: 0.0,
            gk_attributes: None,
            save_probability_override: None,
            is_long: true,
            target_is_space: false,
            retention_probability: 1.0,
            technical_probability: 1.0,
            technical_roll: 0.0,
            delivery_miss: false,
            arrival_snapshot: Some(arrival_snapshot),
            arrival_plan: Some(arrival),
            clearance_transition: None,
            possession_id: state.possession_id,
            restart_origin: None,
            aerial_contest: None,
        };
        let receiver_before = home[receiver_idx].pos;
        let support_before = home[supporting_idx].pos;
        let mut rng = RunnerRng::new(20260714);

        move_flight_players(
            &mut home,
            &mut away,
            flight.clone(),
            state.ball.position,
            &mut state,
            1,
            &config,
            true,
            &mut rng,
            1.0,
        );

        assert_eq!(flight.target, target);
        assert_eq!(flight.ticks_total, 4);
        assert!(
            distance(home[receiver_idx].pos, target) < distance(receiver_before, target),
            "the intended receiver must still run toward the original target"
        );
        assert!(
            home[supporting_idx].movement_intent != "attack_run"
                && home[supporting_idx].target_pos != target,
            "a teammate in the corridor may preserve shape, but must not take over the receiver task"
        );
        assert!(
            distance(home[supporting_idx].pos, support_before)
                <= crate::physics::player_speed(
                    home[supporting_idx].speed.round() as i32,
                    config.player_max_speed,
                    config.player_min_speed,
                ) * 1.05,
            "support movement remains continuous"
        );
    }

    #[test]
    fn misplaced_pass_does_not_reveal_sampled_endpoint_to_intended_receiver() {
        let cards = (0..RUNNER_TEAM_SIZE)
            .map(|index| runner_test_card(format!("Player {index}").as_str(), 75.0, 75.0))
            .collect::<Vec<_>>();
        let home = build_players(&cards, formation_data("442"), true, 105.0, 68.0);
        let away = build_players(&cards, formation_data("442"), false, 105.0, 68.0);
        let passer_idx = 8;
        let receiver_idx = 9;
        let declared_target = (72.0, 34.0);
        let sampled_miss_target = (72.0, 42.0);
        let snapshot = runner_pass_arrival_snapshot(
            passer_idx,
            Some(receiver_idx),
            declared_target,
            &home,
            &away,
        );
        let flight = RunnerFlight {
            kind: RunnerFlightKind::Pass,
            replay_id: 1,
            replay_start_tick: 0.0,
            origin: (40.0, 34.0),
            target: sampled_miss_target,
            ticks_elapsed: 0,
            ticks_total: 2,
            passer_idx,
            passer_team_home: true,
            intended_receiver_idx: Some(receiver_idx),
            offside_flags: [false; RUNNER_TEAM_SIZE],
            last_passer_team_home: None,
            last_passer_idx: -1,
            on_target: false,
            speed: 24.0,
            xg: 0.0,
            gk_attributes: None,
            save_probability_override: None,
            is_long: true,
            target_is_space: false,
            retention_probability: 0.5,
            technical_probability: 0.5,
            technical_roll: 0.9,
            delivery_miss: true,
            arrival_snapshot: Some(snapshot),
            arrival_plan: None,
            clearance_transition: None,
            possession_id: 1,
            restart_origin: None,
            aerial_contest: None,
        };

        assert_eq!(runner_flight_receiver_run_target(&flight), declared_target);
        assert_ne!(
            runner_flight_receiver_run_target(&flight),
            sampled_miss_target
        );
        let config = runtime_config(&json!({}));
        let mut alternate_hidden_target = flight.clone();
        alternate_hidden_target.target = (90.0, 10.0);
        let observed =
            runner_observed_flight_destination(&flight, (40.0, 34.0), (55.0, 38.0), &config);
        assert_eq!(
            observed,
            runner_observed_flight_destination(
                &alternate_hidden_target,
                (40.0, 34.0),
                (55.0, 38.0),
                &config,
            ),
            "visible trajectory extrapolation must not read the hidden sampled endpoint"
        );
        assert_eq!(observed, (85.0, 46.0));

        let mut moved_home = home.clone();
        let mut moved_away = away.clone();
        let mut movement_state = runner_test_state();
        movement_state.ball.position = (55.0, 38.0);
        let mut movement_rng = RunnerRng::new(20260713);
        move_flight_players(
            &mut moved_home,
            &mut moved_away,
            flight,
            (40.0, 34.0),
            &mut movement_state,
            1,
            &config,
            true,
            &mut movement_rng,
            1.0,
        );
        let first_home_positions = moved_home
            .iter()
            .map(|player| player.pos)
            .collect::<Vec<_>>();
        let first_away_positions = moved_away
            .iter()
            .map(|player| player.pos)
            .collect::<Vec<_>>();

        moved_home = home;
        moved_away = away;
        movement_state.ball.position = (55.0, 38.0);
        movement_rng = RunnerRng::new(20260713);
        move_flight_players(
            &mut moved_home,
            &mut moved_away,
            alternate_hidden_target,
            (40.0, 34.0),
            &mut movement_state,
            1,
            &config,
            true,
            &mut movement_rng,
            1.0,
        );

        for index in 0..RUNNER_TEAM_SIZE {
            assert_eq!(
                first_home_positions[index], moved_home[index].pos,
                "attacking player {index} must not move from a hidden sampled endpoint"
            );
            assert_eq!(
                first_away_positions[index], moved_away[index].pos,
                "defending player {index} must not move from a hidden sampled endpoint"
            );
        }
    }

