    #[test]
    fn continuous_take_on_episode_records_only_the_first_contact() {
        let mut state = runner_test_state();
        let episode = RunnerTakeOnEpisode {
            holder_idx: 6,
            holder_team_home: true,
            defender_idx: 1,
            possession_id: state.possession_id,
            carrier_contact_pos: (52.5, 34.0),
            defender_contact_pos: (53.0, 34.0),
            approach_direction: (1.0, 0.0),
        };

        assert!(begin_runner_take_on(&mut state, episode));
        assert!(!begin_runner_take_on(&mut state, episode));
        assert!(begin_runner_take_on(
            &mut state,
            RunnerTakeOnEpisode {
                defender_idx: 2,
                ..episode
            },
        ));
        assert!(begin_runner_take_on(
            &mut state,
            RunnerTakeOnEpisode {
                possession_id: episode.possession_id + 1,
                ..episode
            },
        ));
    }

    #[test]
    fn carry_contact_episode_identity_is_scoped_to_one_contact_pair_and_possession() {
        let episode = RunnerCarryContactEpisode {
            holder_idx: 6,
            holder_team_home: true,
            defender_idx: 1,
            possession_id: 4,
        };
        assert_eq!(episode, RunnerCarryContactEpisode { ..episode });
        assert_ne!(
            episode,
            RunnerCarryContactEpisode {
                defender_idx: 2,
                ..episode
            }
        );
        assert_ne!(
            episode,
            RunnerCarryContactEpisode {
                possession_id: 5,
                ..episode
            }
        );
        assert_ne!(
            episode,
            RunnerCarryContactEpisode {
                holder_idx: 7,
                ..episode
            }
        );
    }

