fn runner_projected_contact_position(
    player: &RunnerPlayer,
    contact_target: (f64, f64),
    duration_ticks: i32,
    movement_intent: &str,
    config: &RunnerRuntimeConfig,
) -> (f64, f64) {
    let mut pos = player.pos;
    let mut velocity = player.velocity;
    for _ in 0..duration_ticks.max(0) {
        let movement = player_move_tick(&PlayerMoveTickInput {
            pos,
            target_pos: contact_target,
            velocity,
            speed_ability: player.speed.round() as i32,
            movement_intent,
            state: player.state.as_str(),
            player_max_speed: config.player_max_speed,
            player_min_speed: config.player_min_speed,
            pitch_length: config.pitch_length,
            pitch_width: config.pitch_width,
        });
        pos = movement.pos;
        velocity = movement.velocity;
    }
    pos
}

fn move_runner_player_to_local_task_fraction(
    player: &mut RunnerPlayer,
    target: (f64, f64),
    movement_intent: &str,
    config: &RunnerRuntimeConfig,
    tick_fraction: f64,
) {
    let movement = player_move_tick_fraction(
        &PlayerMoveTickInput {
            pos: player.pos,
            target_pos: target,
            velocity: player.velocity,
            speed_ability: player.speed.round() as i32,
            movement_intent,
            state: player.state.as_str(),
            player_max_speed: config.player_max_speed,
            player_min_speed: config.player_min_speed,
            pitch_length: config.pitch_length,
            pitch_width: config.pitch_width,
        },
        tick_fraction,
    );
    player.target_pos = target;
    update_runner_text(&mut player.movement_intent, movement_intent);
    player.pos = movement.pos;
    player.velocity = movement.velocity;
    if let Some(facing) = movement.facing_direction {
        player.facing_direction = facing;
    }
    player.distance_covered += movement.distance_covered;
}

fn orient_receiver_to_incoming_ball(
    player: &mut RunnerPlayer,
    ball_pos: (f64, f64),
    attacking_right: bool,
    pitch_width: f64,
    tick_fraction: f64,
) {
    if distance(player.pos, ball_pos) <= 1e-9 {
        return;
    }
    let incoming_heading = angle_between_points(player.pos, ball_pos);
    let attacking_heading: f64 = if attacking_right { 0.0 } else { 180.0 };
    let incoming_radians = incoming_heading.to_radians();
    let attacking_radians = attacking_heading.to_radians();
    let heading_vector = (
        incoming_radians.cos() + attacking_radians.cos(),
        incoming_radians.sin() + attacking_radians.sin(),
    );
    let target_heading = if heading_vector.0.hypot(heading_vector.1) <= 1e-9 {
        let inward_turn = if player.pos.1 <= pitch_width * 0.5 {
            90.0
        } else {
            -90.0
        };
        (attacking_heading + inward_turn).rem_euclid(360.0)
    } else {
        heading_vector
            .1
            .atan2(heading_vector.0)
            .to_degrees()
            .rem_euclid(360.0)
    };
    let awareness = (player.iq / 100.0).clamp(0.0, 1.0);
    let mobility = (player.speed / 100.0).clamp(0.0, 1.0);
    let turn_capacity = (42.0 + 38.0 * awareness + 20.0 * mobility) * tick_fraction.clamp(0.0, 1.0);
    let turn = crate::angle_diff(player.facing_direction, target_heading)
        .clamp(-turn_capacity, turn_capacity);
    player.facing_direction = (player.facing_direction + turn).rem_euclid(360.0);
}

fn advance_pass_receiver_fraction(
    player: &mut RunnerPlayer,
    receiver_run_target: (f64, f64),
    visible_ball_pos: (f64, f64),
    attacking_right: bool,
    config: &RunnerRuntimeConfig,
    tick_fraction: f64,
) {
    player.target_pos = receiver_run_target;
    update_runner_text(&mut player.movement_intent, "attack_run");
    let movement = crate::player_move_elapsed_seconds(
        &PlayerMoveTickInput {
            pos: player.pos,
            target_pos: receiver_run_target,
            velocity: player.velocity,
            speed_ability: player.speed.round() as i32,
            movement_intent: "attack_run",
            state: player.state.as_str(),
            player_max_speed: config.player_max_speed,
            player_min_speed: config.player_min_speed,
            pitch_length: config.pitch_length,
            pitch_width: config.pitch_width,
        },
        tick_fraction * config.tick_duration,
        config.tick_duration,
    );
    player.pos = movement.pos;
    player.velocity = movement.velocity;
    if let Some(facing) = movement.facing_direction {
        player.facing_direction = facing;
    }
    player.distance_covered += movement.distance_covered;
    orient_receiver_to_incoming_ball(
        player,
        visible_ball_pos,
        attacking_right,
        config.pitch_width,
        tick_fraction * config.tick_duration,
    );
}

fn runner_projected_defender_from_player(
    index: usize,
    player: &RunnerPlayer,
) -> RunnerProjectedDefender {
    RunnerProjectedDefender {
        index,
        pos: player.pos,
        target_pos: player.target_pos,
        tactical_anchor: player.tactical_anchor,
        base_pos: player.base_pos,
        velocity: player.velocity,
        speed: player.speed,
        defence: player.defence,
        tackling: player.tackling,
        iq: player.iq,
        gk_saving: player.gk_saving,
        gk_positioning: player.gk_positioning,
        gk_reaction: player.gk_reaction,
        state: if player.state == "pressing" {
            "pressing"
        } else if player.state == "stunned" {
            "stunned"
        } else {
            "off_ball"
        },
        last_def_action: runner_static_defense_action(player.last_def_action.as_str()),
        is_goalkeeper: player.position == "GK",
    }
}

fn runner_carry_defender_responses(
    holder_idx: usize,
    holder: &RunnerPlayer,
    attackers: &[RunnerPlayer],
    opponents: &[RunnerPlayer],
    current_control: PossessionControlState,
    carry_target: (f64, f64),
    attacking_right: bool,
    plan_signals: TeamPlanSignals,
    segment_count: i32,
    config: &RunnerRuntimeConfig,
) -> RunnerCarryDefenderResponses {
    let segment_count = segment_count.max(1) as usize;
    let mut responses = RunnerCarryDefenderResponses::new(segment_count, opponents.len());
    let mut scratch = RunnerCarryDefenderResponseScratch::new();
    let mut projected_defenders = [RUNNER_EMPTY_PROJECTED_DEFENDER; RUNNER_TEAM_SIZE];
    for (index, opponent) in opponents.iter().enumerate() {
        projected_defenders[index] = runner_projected_defender_from_player(index, opponent);
    }
    let mut projected_attackers = [CarrySupportPlayer {
        index: 0,
        pos: (0.0, 0.0),
        base: (0.0, 0.0),
        finishing: 0.0,
        long_shot: 0.0,
        is_goalkeeper: false,
    }; RUNNER_TEAM_SIZE];
    for (index, attacker) in attackers.iter().enumerate() {
        projected_attackers[index] = CarrySupportPlayer {
            index,
            pos: attacker.pos,
            base: attacker.base_pos,
            finishing: attacker.finishing / 100.0,
            long_shot: attacker.long_shot / 100.0,
            is_goalkeeper: attacker.position == "GK",
        };
    }
    runner_carry_defender_responses_into(
        holder_idx,
        holder,
        &projected_attackers[..attackers.len()],
        &projected_defenders[..opponents.len()],
        current_control,
        carry_target,
        attacking_right,
        plan_signals,
        segment_count as i32,
        config,
        &mut responses,
        &mut scratch,
    );
    responses
}

fn goalkeeper_carry_smother_target(
    goalkeeper: &RunnerProjectedDefender,
    carrier_pos: (f64, f64),
    carrier_velocity: (f64, f64),
    carry_target: (f64, f64),
    attacking_right: bool,
    plan_signals: TeamPlanSignals,
    config: &RunnerRuntimeConfig,
) -> Option<(f64, f64)> {
    let attack_direction = if attacking_right { 1.0 } else { -1.0 };
    let inertial_target = (
        carrier_pos.0 + carrier_velocity.0,
        carrier_pos.1 + carrier_velocity.1,
    );
    let effective_motion_target = if (inertial_target.0 - carrier_pos.0) * attack_direction
        > (carry_target.0 - carrier_pos.0) * attack_direction
    {
        inertial_target
    } else {
        carry_target
    };
    let segment_distance = distance(carrier_pos, effective_motion_target).min(config.carrier_speed);
    let segment_fraction =
        segment_distance / distance(carrier_pos, effective_motion_target).max(1e-9);
    let carrier_segment_end = (
        carrier_pos.0 + (effective_motion_target.0 - carrier_pos.0) * segment_fraction,
        carrier_pos.1 + (effective_motion_target.1 - carrier_pos.1) * segment_fraction,
    );
    goalkeeper_carry_smother_target_with_motion_target(
        goalkeeper,
        carrier_pos,
        effective_motion_target,
        carrier_segment_end,
        attacking_right,
        plan_signals,
        config,
    )
}

fn goalkeeper_carry_smother_target_for_segment(
    goalkeeper: &RunnerProjectedDefender,
    carrier_pos: (f64, f64),
    carrier_segment_end: (f64, f64),
    carrier_lookahead_end: (f64, f64),
    attacking_right: bool,
    plan_signals: TeamPlanSignals,
    config: &RunnerRuntimeConfig,
) -> Option<(f64, f64)> {
    goalkeeper_carry_smother_target_with_motion_target(
        goalkeeper,
        carrier_pos,
        carrier_lookahead_end,
        carrier_segment_end,
        attacking_right,
        plan_signals,
        config,
    )
}

fn goalkeeper_carry_smother_target_with_motion_target(
    goalkeeper: &RunnerProjectedDefender,
    carrier_pos: (f64, f64),
    effective_motion_target: (f64, f64),
    carrier_segment_end: (f64, f64),
    attacking_right: bool,
    plan_signals: TeamPlanSignals,
    config: &RunnerRuntimeConfig,
) -> Option<(f64, f64)> {
    let attack_direction = if attacking_right { 1.0 } else { -1.0 };
    let goal_x = if attacking_right {
        config.pitch_length
    } else {
        0.0
    };
    let goalward_progress = (effective_motion_target.0 - carrier_pos.0) * attack_direction;
    let carrier_depth = (goal_x - carrier_pos.0) * attack_direction;
    let target_depth = (goal_x - effective_motion_target.0) * attack_direction;
    let goalkeeper_depth = (goal_x - goalkeeper.pos.0) * attack_direction;
    let penalty_half_width = 20.2;
    let six_yard_depth = 5.5;
    let lateral_progress = (effective_motion_target.1 - carrier_pos.1).abs();
    let lateral_six_yard_carry = carrier_depth <= six_yard_depth
        && target_depth <= six_yard_depth
        && carrier_depth >= -0.5
        && lateral_progress > 0.15;
    let effective_threat_target = if target_depth < 0.0 {
        let path_fraction = ((goal_x - carrier_pos.0)
            / (effective_motion_target.0 - carrier_pos.0))
            .clamp(0.0, 1.0);
        (
            goal_x,
            carrier_pos.1 + (effective_motion_target.1 - carrier_pos.1) * path_fraction,
        )
    } else {
        effective_motion_target
    };
    if (goalward_progress <= 0.15 && !lateral_six_yard_carry)
        || target_depth > 16.5
        || goalkeeper_depth < -0.5
        || goalkeeper_depth > 16.5
        || (effective_threat_target.1 - config.pitch_width * 0.5).abs() > penalty_half_width
    {
        return None;
    }

    let threat_path = (
        effective_threat_target.0 - carrier_pos.0,
        effective_threat_target.1 - carrier_pos.1,
    );
    let threat_path_length_squared = threat_path.0 * threat_path.0 + threat_path.1 * threat_path.1;
    if threat_path_length_squared <= 1e-9 {
        return None;
    }
    let offset = (
        goalkeeper.pos.0 - carrier_pos.0,
        goalkeeper.pos.1 - carrier_pos.1,
    );
    let threat_path_fraction = ((offset.0 * threat_path.0 + offset.1 * threat_path.1)
        / threat_path_length_squared)
        .clamp(0.12, 1.0);
    let threat_interception = (
        carrier_pos.0 + threat_path.0 * threat_path_fraction,
        carrier_pos.1 + threat_path.1 * threat_path_fraction,
    );

    let segment_target_depth = (goal_x - carrier_segment_end.0) * attack_direction;
    let effective_segment_target = if segment_target_depth < 0.0 {
        let path_fraction =
            ((goal_x - carrier_pos.0) / (carrier_segment_end.0 - carrier_pos.0)).clamp(0.0, 1.0);
        (
            goal_x,
            carrier_pos.1 + (carrier_segment_end.1 - carrier_pos.1) * path_fraction,
        )
    } else {
        carrier_segment_end
    };
    let path = (
        effective_segment_target.0 - carrier_pos.0,
        effective_segment_target.1 - carrier_pos.1,
    );
    let path_length_squared = path.0 * path.0 + path.1 * path.1;
    if path_length_squared <= 1e-9 {
        return None;
    }
    let path_fraction =
        ((offset.0 * path.0 + offset.1 * path.1) / path_length_squared).clamp(0.12, 1.0);
    let interception = (
        carrier_pos.0 + path.0 * path_fraction,
        carrier_pos.1 + path.1 * path_fraction,
    );
    let threat_path_distance = distance(goalkeeper.pos, threat_interception);
    let reaction = (goalkeeper.gk_reaction / 100.0).clamp(0.0, 1.0);
    let positioning = (goalkeeper.gk_positioning / 100.0).clamp(0.0, 1.0);
    let saving = (goalkeeper.gk_saving / 100.0).clamp(0.0, 1.0);
    let smother_reach = 2.4
        + 2.2 * (goalkeeper.speed / 100.0).clamp(0.0, 1.0)
        + 1.2 * reaction
        + 0.8 * positioning
        + 0.6 * saving;
    if threat_path_distance <= smother_reach {
        return Some(interception);
    }

    let movement = crate::off_ball_defense::project_defense_action_motion(
        goalkeeper.pos,
        interception,
        goalkeeper.tactical_anchor,
        "smother",
        runner_projected_defense_movement_input(goalkeeper, plan_signals, config),
    );
    let relative_start = (
        carrier_pos.0 - goalkeeper.pos.0,
        carrier_pos.1 - goalkeeper.pos.1,
    );
    let relative_velocity = (
        (carrier_segment_end.0 - carrier_pos.0) - (movement.pos.0 - goalkeeper.pos.0),
        (carrier_segment_end.1 - carrier_pos.1) - (movement.pos.1 - goalkeeper.pos.1),
    );
    let relative_speed_squared =
        relative_velocity.0 * relative_velocity.0 + relative_velocity.1 * relative_velocity.1;
    let closest_time = if relative_speed_squared <= 1e-9 {
        0.0
    } else {
        (-(relative_start.0 * relative_velocity.0 + relative_start.1 * relative_velocity.1)
            / relative_speed_squared)
            .clamp(0.0, 1.0)
    };
    let closest_separation = (
        relative_start.0 + relative_velocity.0 * closest_time,
        relative_start.1 + relative_velocity.1 * closest_time,
    );
    let dynamic_distance = (closest_separation.0 * closest_separation.0
        + closest_separation.1 * closest_separation.1)
        .sqrt();
    let physical_reach = defender_action_physical_reach(config.tackle_range, "smother");
    (dynamic_distance < physical_reach).then_some(interception)
}

fn runner_carry_defender_responses_into(
    holder_idx: usize,
    holder: &RunnerPlayer,
    attackers: &[CarrySupportPlayer],
    defenders: &[RunnerProjectedDefender],
    current_control: PossessionControlState,
    carry_target: (f64, f64),
    attacking_right: bool,
    plan_signals: TeamPlanSignals,
    segment_count: i32,
    config: &RunnerRuntimeConfig,
    responses: &mut RunnerCarryDefenderResponses,
    scratch: &mut RunnerCarryDefenderResponseScratch,
) {
    let segment_count = segment_count.max(1) as usize;
    responses.action_origin = holder.pos;
    assert!(
        segment_count <= RUNNER_MAX_CARRY_RESPONSE_SEGMENTS,
        "carry response segment count exceeds action timing bound"
    );
    assert!(
        defenders.len() <= RUNNER_TEAM_SIZE,
        "carry defender responses expect an eleven-player defense"
    );
    let RunnerCarryDefenderResponseScratch {
        projected_defenders,
        attacker_positions,
        control_teammates,
        control_goalkeeper_indices,
        control_opponents,
        execution_opponents,
        targets,
        action_types,
        team_defenders,
        defender_team_context_indices,
    } = scratch;
    projected_defenders[..defenders.len()].copy_from_slice(defenders);
    let projected_defenders = &mut projected_defenders[..defenders.len()];
    let mut static_attacker_count = 0;
    let mut control_goalkeeper_count = 0;
    for player in attackers {
        control_teammates[player.index] = (player.index, player.pos.0, player.pos.1);
        if player.is_goalkeeper {
            control_goalkeeper_indices[control_goalkeeper_count] = player.index;
            control_goalkeeper_count += 1;
        }
        if player.index == holder_idx || player.is_goalkeeper {
            continue;
        }
        attacker_positions[static_attacker_count] = player.pos;
        static_attacker_count += 1;
    }
    let mut projected_control = current_control;
    let carry_heading = angle_between_points(holder.pos, carry_target);
    let mut projected_carrier_pos = holder.pos;
    let mut projected_carrier_velocity = holder.velocity;

    for segment in 0..segment_count {
        let carrier_pos = projected_carrier_pos;
        control_teammates[holder_idx] = (holder_idx, carrier_pos.0, carrier_pos.1);
        let carrier_control_readiness =
            crate::directional_control_readiness(projected_control, carry_heading);
        responses.control_readiness[segment] = carrier_control_readiness;
        responses.control_readiness_count = segment + 1;
        attacker_positions[static_attacker_count] = carrier_pos;
        let attacker_count = static_attacker_count + 1;
        let mut team_defender_count = 0;
        let mut control_opponent_count = 0;
        for (defender_idx, defender) in projected_defenders.iter().enumerate() {
            execution_opponents[defender_idx] = ExecutionOpponent {
                pos: defender.pos,
                is_goalkeeper: defender.is_goalkeeper,
            };
            if defender.is_goalkeeper {
                continue;
            }
            control_opponents[control_opponent_count] = defender.pos;
            control_opponent_count += 1;
            team_defenders[team_defender_count] = DefenseTeammateInput {
                pos: defender.pos,
                target_pos: defender.target_pos,
                anchor: defender.tactical_anchor,
            };
            defender_team_context_indices[defender_idx] = team_defender_count;
            team_defender_count += 1;
        }
        let team_context = fixed_defense_team_context(
            carrier_pos,
            Some(carrier_pos),
            holder.possession_ticks + segment as i32 + 1,
            config.tick_duration,
            carrier_control_readiness,
            !attacking_right,
            config.pitch_length,
            config.pitch_width,
            config.press_radius,
            &team_defenders[..team_defender_count],
        );
        for defender_idx in 0..projected_defenders.len() {
            let defender = &projected_defenders[defender_idx];
            if defender.is_goalkeeper {
                if let Some(target) = goalkeeper_carry_smother_target(
                    defender,
                    carrier_pos,
                    projected_carrier_velocity,
                    carry_target,
                    attacking_right,
                    plan_signals,
                    config,
                ) {
                    targets[defender_idx] = target;
                    action_types[defender_idx] = "smother";
                } else {
                    targets[defender_idx] = defender.target_pos;
                    action_types[defender_idx] = "hold_position";
                }
                continue;
            }
            let choice = best_fixed_team_defense_candidate_with_team_context(
                &DefenseChoiceInput {
                    defender_pos: defender.pos,
                    anchor: defender.tactical_anchor,
                    base_ref: defender.base_pos,
                    ball_pos: carrier_pos,
                    ball_carrier_pos: Some(carrier_pos),
                    carrier_velocity: projected_carrier_velocity,
                    ball_carrier_consecutive_carries: holder.consecutive_carries
                        + segment as i32
                        + 1,
                    ball_carrier_possession_ticks: holder.possession_ticks + segment as i32 + 1,
                    carrier_control_readiness,
                    attacking_right: !attacking_right,
                    pitch_length: config.pitch_length,
                    pitch_width: config.pitch_width,
                    press_radius: config.press_radius,
                    tackle_range: config.tackle_range,
                    carrier_speed: config.carrier_speed,
                    press_intensity: plan_signals.press_intensity,
                    compactness: plan_signals.compactness,
                    movement: runner_projected_defense_movement_input(
                        defender,
                        plan_signals,
                        config,
                    ),
                    iq: defender.iq,
                    attackers: &attacker_positions[..attacker_count],
                    teammates: &[],
                    random_samples: &[],
                    score_noises: &[],
                    roll_by_count: &[],
                    fallback_index_by_count: &[],
                },
                Some((&team_context, defender_team_context_indices[defender_idx])),
            );
            let choice = choice.map(|candidate| (candidate.target, candidate.action_type));
            let (target, action) =
                choice.unwrap_or((defender.target_pos, defender.last_def_action));
            targets[defender_idx] = target;
            action_types[defender_idx] = action;
        }
        for (defender_idx, defender) in projected_defenders.iter_mut().enumerate() {
            let target = targets[defender_idx];
            let action = action_types[defender_idx];
            let movement = crate::off_ball_defense::project_defense_action_motion(
                defender.pos,
                target,
                defender.tactical_anchor,
                action,
                runner_projected_defense_movement_input(defender, plan_signals, config),
            );
            responses.segments[segment][defender_idx] = DefenderActionInput {
                index: defender.index,
                pos: defender.pos,
                new_pos: movement.pos,
                action,
                speed: defender.speed,
                defence: defender.defence,
                tackling: defender.tackling,
                gk_saving: defender.gk_saving,
                gk_positioning: defender.gk_positioning,
                gk_reaction: defender.gk_reaction,
                is_goalkeeper: defender.is_goalkeeper,
            };
            defender.pos = movement.pos;
            defender.velocity = movement.velocity;
            defender.target_pos = target;
            defender.last_def_action = action;
        }
        let carry = carry_phase_plan(&CarryPhasePlanInput {
            transition: None,
            holder_pos: projected_carrier_pos,
            terminal_touch_origin: Some(holder.pos),
            target: carry_target,
            velocity: projected_carrier_velocity,
            speed_ability: holder.speed.round() as i32,
            dribbling: holder.dribbling,
            consecutive_carries: holder.consecutive_carries + segment as i32,
            control_readiness: carrier_control_readiness,
            attacking_right,
            pitch_length: config.pitch_length,
            pitch_width: config.pitch_width,
            goal_width: config.goal_width,
            player_max_speed: config.player_max_speed,
            player_min_speed: config.player_min_speed,
            carrier_speed: config.carrier_speed,
            carry_error_divisor: config.carry_error_divisor,
            opponents: &execution_opponents[..projected_defenders.len()],
            defender_responses: &responses.segments[segment][..projected_defenders.len()],
            error_roll: 1.0,
            containment_roll: 1.0,
            loose_x_roll: 0.5,
            loose_y_roll: 0.5,
        });
        projected_carrier_pos = carry.new_pos;
        projected_carrier_velocity = carry.velocity;
        projected_control =
            crate::transition_possession_control(&PossessionControlTransitionInput {
                previous: projected_control,
                observation: PossessionControlObservation {
                    controller_index: holder_idx,
                    controller_pos: projected_carrier_pos,
                    teammate_positions: &control_teammates[..attackers.len()],
                    teammate_goalkeeper_indices: &control_goalkeeper_indices
                        [..control_goalkeeper_count],
                    opponent_positions: &control_opponents[..control_opponent_count],
                    pitch_length: config.pitch_length,
                    pitch_width: config.pitch_width,
                    attacking_right,
                },
                arrival_heading: carry.facing_direction.unwrap_or(carry_heading),
                ownership_continuity: 1.0,
                contact_load: carry.contact_load,
                settling_ticks: 1,
                tick_duration: config.tick_duration,
                elapsed_fraction: 1.0,
                movement_distance: carry.distance_covered,
                turn_target: None,
            });
    }
    responses.projected_carrier_pos = projected_carrier_pos;
    responses.successor_control = projected_control;
    responses.projected_goalkeeper_pos = projected_defenders
        .iter()
        .find(|defender| defender.is_goalkeeper)
        .map(|goalkeeper| goalkeeper.pos);
}

fn runner_static_defense_action(action: &str) -> &'static str {
    match action {
        "close_down" => "close_down",
        "tackle" => "tackle",
        "tackle_committed" => "tackle_committed",
        "tackle_spent" => "tackle_spent",
        "approach" => "approach",
        "pursuit" => "close_down",
        "mark_runner" => "mark_runner",
        "block_lane" => "block_lane",
        "smother" => "smother",
        _ => "hold_position",
    }
}

fn runner_control_interference_probability(
    control_pos: (f64, f64),
    defenders: &[RunnerPlayer],
    projected_positions: &[(usize, f64, f64)],
) -> f64 {
    assert!(
        defenders.len() <= RUNNER_TEAM_SIZE,
        "control interference expects eleven-player teams"
    );
    let mut inputs = [RUNNER_EMPTY_DEFENDER_ACTION; RUNNER_TEAM_SIZE];
    for (index, defender) in defenders.iter().enumerate() {
        let pos = projected_position(projected_positions, index, defender.pos);
        inputs[index] = DefenderActionInput {
            index,
            pos,
            new_pos: pos,
            action: runner_static_defense_action(defender.last_def_action.as_str()),
            speed: defender.speed,
            defence: defender.defence,
            tackling: defender.tackling,
            gk_saving: defender.gk_saving,
            gk_positioning: defender.gk_positioning,
            gk_reaction: defender.gk_reaction,
            is_goalkeeper: defender.position == "GK",
        };
    }
    crate::interactions::control_interference_probability(control_pos, &inputs[..defenders.len()])
}

