#[allow(clippy::too_many_arguments)]
fn runner_projected_control_value_with_shape_inputs(
    controller_idx: usize,
    controller_pos: (f64, f64),
    controlling_players: &[RunnerPlayer],
    defending_players: &[RunnerPlayer],
    shape_inputs: &RunnerProjectedExecutionShapeInputs,
    controlling_are_teammates: bool,
    controlling_home: bool,
    attacking_right: bool,
    controlling_phase: &str,
    defending_phase: &str,
    controlling_plan: TeamPlanState,
    defending_plan: TeamPlanState,
    controlling_signals: TeamPlanSignals,
    defending_signals: TeamPlanSignals,
    previous_control: PossessionControlState,
    arrival_heading: f64,
    ownership_continuity: f64,
    contact_load: f64,
    duration_ticks: i32,
    elapsed_fraction: f64,
    movement_distance: f64,
    turn_target: Option<f64>,
    tick: i32,
    shot_quality_cache: &ShotQualityCache,
    value_context: &mut RunnerProjectedControlValueContext,
    config: &RunnerRuntimeConfig,
    diagnostic_network_time_budget_seconds: Option<f64>,
) -> (f64, RunnerProjectedStateValueBreakdown) {
    let Some(controller) = controlling_players.get(controller_idx) else {
        return (0.0, RunnerProjectedStateValueBreakdown::default());
    };
    let projection_slot = runner_cache_projected_control_positions_with_shape_inputs(
        controller_idx,
        controller_pos,
        controlling_players,
        defending_players,
        shape_inputs,
        controlling_are_teammates,
        controlling_home,
        attacking_right,
        controlling_phase,
        defending_phase,
        controlling_plan,
        defending_plan,
        controlling_signals,
        defending_signals,
        duration_ticks,
        elapsed_fraction,
        tick,
        shot_quality_cache,
        value_context,
        config,
    );
    let projection = &value_context.projection_cache.entries[projection_slot];
    let projected_controlling = &projection.controlling;
    let control_state = crate::transition_possession_control(&PossessionControlTransitionInput {
        previous: previous_control,
        observation: PossessionControlObservation {
            controller_index: controller_idx,
            controller_pos,
            teammate_positions: projected_controlling.slice(),
            teammate_goalkeeper_indices: &value_context
                .state_value_inputs
                .teammate_goalkeeper_indices
                [..value_context.state_value_inputs.teammate_goalkeeper_count],
            opponent_positions: &projection.projected_defender_positions
                [..projection.projected_defender_count],
            pitch_length: config.pitch_length,
            pitch_width: config.pitch_width,
            attacking_right,
        },
        arrival_heading,
        ownership_continuity,
        contact_load,
        settling_ticks: duration_ticks,
        tick_duration: config.tick_duration,
        elapsed_fraction,
        movement_distance,
        turn_target,
    });

    let input = StateValueInput {
        pos: controller_pos,
        player_index: controller_idx,
        shot_profiles: &value_context.state_value_inputs.shot_profiles
            [..value_context.state_value_inputs.shot_profile_count],
        teammate_positions: &projection.projected_teammate_positions
            [..projection.projected_teammate_count],
        teammate_goalkeeper_indices: &value_context.state_value_inputs.teammate_goalkeeper_indices
            [..value_context.state_value_inputs.teammate_goalkeeper_count],
        opponent_positions: &projection.projected_defender_positions
            [..projection.projected_defender_count],
        pitch_length: config.pitch_length,
        pitch_width: config.pitch_width,
        attacking_right,
        offside_line: projection.offside_line,
        finishing: controller.finishing / 100.0,
        long_shot: controller.long_shot / 100.0,
        shot_ideal_distance: config.shot_ideal_distance,
        shot_on_target_base: config.shot_on_target_base,
        gk_save_base: config.gk_save_base,
        gk_attributes: Some(value_context.defending_gk_attributes),
        gk_pos: projection.projected_gk_pos,
        contest_defenders: Some(
            &projection.projected_contest_defenders
                [..value_context.defending_contest_defender_count],
        ),
        tick: tick + duration_ticks.max(0),
        team_home: controlling_home,
        shot_quality_cache: Some(shot_quality_cache),
        control_state: Some(control_state),
    };
    let state = possession_state_value_with_context_and_bellman_geometry(
        &input,
        &projection.possession_value_context,
        &projection.bellman_geometry,
    );
    let mut breakdown = RunnerProjectedStateValueBreakdown::default();
    breakdown.add_weighted(state, 1.0);
    // This counterfactual only populates the trace ledger. Keeping it out of
    // the default production path avoids a second full state-value network
    // evaluation for every projected branch without changing action values.
    if config.trace_detail != "off" {
        let symmetric_goalkeeper_network =
            crate::state_value::diagnostic_possession_state_value_with_goalkeeper_recycle_node(
                &input,
            );
        breakdown.symmetric_goalkeeper_network_applied = true;
        breakdown.symmetric_goalkeeper_network_continuation_value =
            symmetric_goalkeeper_network.continuation_value;
    }
    if config.trace_detail == "full" {
        let symmetric_field_shape =
            crate::state_value::diagnostic_possession_state_value_with_symmetric_field_shape(
                &input,
                &projection.possession_value_context,
            );
        breakdown.symmetric_field_shape_applied = true;
        breakdown.symmetric_field_shape_structure = symmetric_field_shape.structure;
        breakdown.symmetric_field_shape_continuation_value =
            symmetric_field_shape.continuation_value;
    }
    if let Some(time_budget_seconds) = diagnostic_network_time_budget_seconds {
        let link_duration_state = crate::state_value::diagnostic_possession_state_value_with_context_and_bellman_geometry_link_duration(
            &input,
            &projection.possession_value_context,
            &projection.bellman_geometry,
            config.ball_pass_speed,
            config.tick_duration,
            controlling_signals.tempo,
        );
        let time_budget_state = crate::state_value::diagnostic_possession_state_value_with_context_and_bellman_geometry_time_budget(
            &input,
            &projection.possession_value_context,
            &projection.bellman_geometry,
            config.ball_pass_speed,
            config.tick_duration,
            time_budget_seconds,
        );
        breakdown.network_link_duration_applied = true;
        breakdown.link_duration_continuation_value =
            link_duration_state.continuation_value;
        breakdown.network_time_budget_applied = true;
        breakdown.network_time_budget_seconds = time_budget_seconds;
        breakdown.time_budget_continuation_value = time_budget_state.continuation_value;
    }
    (state.value, breakdown)
}

